CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE SCHEMA tenant_template;
SET search_path=tenant_template,extensions,public;
SET check_function_bodies=off;
CREATE TABLE attendance_break_decisions ("id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
"store_id" bigint NOT NULL,
"employee_id" bigint NOT NULL,
"in_event_id" bigint NOT NULL,
"break_provided" boolean,
"compensate_30m" boolean DEFAULT false NOT NULL,
"updated_by" text,
"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE event_corrections ("id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
"event_id" bigint,
"employee_id" bigint NOT NULL,
"action" text NOT NULL,
"new_event_at" timestamp without time zone,
"new_event_type" text,
"reason" text,
"created_by" text,
"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE recipe_versions_demo_archive ("id" bigint NOT NULL,
