"employee_id" bigint NOT NULL,
"employee_name" text NOT NULL,
"hours" numeric,
"wage" integer,
"weeks" integer,
"base_pay" integer,
"juhyu_pay" integer,
"adjust" integer,
"gross_pay" integer,
"tax_rate" numeric,
