ALTER TABLE attendance_break_decisions ADD CONSTRAINT attendance_break_decisions_in_event_id_key UNIQUE (in_event_id);
ALTER TABLE attendance_break_decisions ADD CONSTRAINT attendance_break_decisions_pkey PRIMARY KEY (id);
ALTER TABLE event_corrections ADD CONSTRAINT event_corrections_action_check CHECK ((action = ANY (ARRAY['EDIT_TIME'::text, 'EDIT_TYPE'::text, 'VOID'::text, 'ADD'::text, 'VOID_ADD'::text])));
ALTER TABLE event_corrections ADD CONSTRAINT event_corrections_new_event_type_check CHECK ((new_event_type = ANY (ARRAY['IN'::text, 'OUT'::text])));
ALTER TABLE event_corrections ADD CONSTRAINT event_corrections_pkey PRIMARY KEY (id);
CREATE INDEX idx_corr_emp ON tenant_template.event_corrections USING btree (employee_id, created_at);
CREATE INDEX idx_corr_event ON tenant_template.event_corrections USING btree (event_id);
ALTER TABLE recipe_versions_demo_archive ADD CONSTRAINT recipe_versions_demo_archive_pkey PRIMARY KEY (id);
ALTER TABLE recipe_components_demo_archive ADD CONSTRAINT recipe_components_demo_archive_pkey PRIMARY KEY (recipe_version_id, item_id);
ALTER TABLE store_recipe_overrides ADD CONSTRAINT store_recipe_overrides_components_check CHECK ((jsonb_typeof(components) = 'array'::text));
ALTER TABLE store_recipe_overrides ADD CONSTRAINT store_recipe_overrides_instructions_check CHECK (((instructions IS NULL) OR (jsonb_typeof(instructions) = 'array'::text)));
ALTER TABLE store_recipe_overrides ADD CONSTRAINT store_recipe_overrides_pkey PRIMARY KEY (store_id, menu_key);
ALTER TABLE store_notifications ADD CONSTRAINT store_notifications_pkey PRIMARY KEY (id);
CREATE INDEX store_notifications_store_unread_idx ON tenant_template.store_notifications USING btree (store_id, is_read, created_at DESC);
CREATE INDEX store_notifications_product_id_idx ON tenant_template.store_notifications USING btree (product_id);
ALTER TABLE employees ADD CONSTRAINT employees_pkey PRIMARY KEY (id);
CREATE INDEX employees_store_idx ON tenant_template.employees USING btree (store_id, is_active);
CREATE UNIQUE INDEX employees_store_active_employee_no_uidx ON tenant_template.employees USING btree (store_id, employee_no) WHERE (is_active AND (employee_no IS NOT NULL));
ALTER TABLE attendance_events ADD CONSTRAINT attendance_events_event_type_check CHECK ((event_type = ANY (ARRAY['IN'::text, 'OUT'::text])));
ALTER TABLE attendance_events ADD CONSTRAINT attendance_events_pkey PRIMARY KEY (id);
CREATE INDEX idx_att_emp_time ON tenant_template.attendance_events USING btree (employee_id, event_at);
CREATE INDEX attendance_events_substitute_for_idx ON tenant_template.attendance_events USING btree (substitute_for_employee_id) WHERE (substitute_for_employee_id IS NOT NULL);
ALTER TABLE correction_requests ADD CONSTRAINT correction_requests_kind_check CHECK ((kind = ANY (ARRAY['MISSING_OUT'::text, 'MISSING_IN'::text, 'WRONG_TIME'::text, 'OTHER'::text])));
ALTER TABLE correction_requests ADD CONSTRAINT correction_requests_pkey PRIMARY KEY (id);
ALTER TABLE correction_requests ADD CONSTRAINT correction_requests_requested_type_check CHECK ((requested_type = ANY (ARRAY['IN'::text, 'OUT'::text])));
ALTER TABLE correction_requests ADD CONSTRAINT correction_requests_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text])));
CREATE INDEX idx_req_status ON tenant_template.correction_requests USING btree (status, created_at);
CREATE INDEX idx_req_emp ON tenant_template.correction_requests USING btree (employee_id);
CREATE INDEX correction_requests_event_id_idx ON tenant_template.correction_requests USING btree (event_id);
ALTER TABLE payroll_period ADD CONSTRAINT payroll_period_pkey PRIMARY KEY (ym);
ALTER TABLE payroll_period ADD CONSTRAINT payroll_period_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'CALCULATED'::text, 'REVIEW'::text, 'CLOSED'::text])));
ALTER TABLE payroll_period_employee ADD CONSTRAINT payroll_period_employee_pkey PRIMARY KEY (ym, employee_id);
CREATE INDEX payroll_period_employee_employee_id_idx ON tenant_template.payroll_period_employee USING btree (employee_id);
ALTER TABLE admin_users ADD CONSTRAINT admin_users_admin_role_check CHECK ((admin_role = ANY (ARRAY['HQ'::text, 'STORE_MANAGER'::text])));
ALTER TABLE admin_users ADD CONSTRAINT admin_users_pkey PRIMARY KEY (user_id);
CREATE INDEX admin_users_store_id_idx ON tenant_template.admin_users USING btree (store_id);
ALTER TABLE payroll_snapshot ADD CONSTRAINT payroll_snapshot_pkey PRIMARY KEY (id);
CREATE UNIQUE INDEX uq_snapshot_ym_emp ON tenant_template.payroll_snapshot USING btree (ym, employee_id);
CREATE INDEX payroll_snapshot_employee_id_idx ON tenant_template.payroll_snapshot USING btree (employee_id);
ALTER TABLE employee_documents ADD CONSTRAINT employee_documents_pkey PRIMARY KEY (id);
ALTER TABLE employee_documents ADD CONSTRAINT employee_documents_storage_path_key UNIQUE (storage_path);
CREATE INDEX idx_empdoc_emp ON tenant_template.employee_documents USING btree (employee_id, uploaded_at DESC);
CREATE INDEX employee_documents_contract_id_idx ON tenant_template.employee_documents USING btree (contract_id, uploaded_at DESC);
ALTER TABLE work_schedules ADD CONSTRAINT work_schedules_employee_id_work_date_key UNIQUE (employee_id, work_date);
ALTER TABLE work_schedules ADD CONSTRAINT work_schedules_pkey PRIMARY KEY (id);
ALTER TABLE work_schedules ADD CONSTRAINT work_schedules_status_check CHECK ((status = ANY (ARRAY['WORK'::text, 'OFF'::text])));
ALTER TABLE work_schedules ADD CONSTRAINT ws_time_rule CHECK ((((status = 'WORK'::text) AND (planned_start IS NOT NULL) AND (planned_end IS NOT NULL) AND (planned_start <> planned_end)) OR ((status = 'OFF'::text) AND (planned_start IS NULL) AND (planned_end IS NULL))));
CREATE INDEX idx_ws_date ON tenant_template.work_schedules USING btree (work_date);
ALTER TABLE work_schedule_history ADD CONSTRAINT work_schedule_history_pkey PRIMARY KEY (id);
CREATE INDEX idx_wsh_emp_date ON tenant_template.work_schedule_history USING btree (employee_id, work_date);
ALTER TABLE recipe_source_components ADD CONSTRAINT recipe_source_components_pkey PRIMARY KEY (id);
ALTER TABLE employment_periods ADD CONSTRAINT employment_period_dates_ck CHECK (((ended_on IS NULL) OR (ended_on >= started_on)));
ALTER TABLE employment_periods ADD CONSTRAINT employment_periods_pkey PRIMARY KEY (id);
CREATE INDEX employment_periods_employee_idx ON tenant_template.employment_periods USING btree (employee_id, started_on, ended_on);
ALTER TABLE employment_contract_workdays ADD CONSTRAINT employment_contract_workdays_minutes_ck CHECK (((contracted_minutes > 0) AND (contracted_minutes < 1440)));
ALTER TABLE employment_contract_workdays ADD CONSTRAINT employment_contract_workdays_pkey PRIMARY KEY (contract_id, weekday);
ALTER TABLE employment_contract_workdays ADD CONSTRAINT employment_contract_workdays_time_ck CHECK ((planned_start <> planned_end));
ALTER TABLE employment_contract_workdays ADD CONSTRAINT employment_contract_workdays_weekday_ck CHECK (((weekday >= 0) AND (weekday <= 6)));
ALTER TABLE absence_decisions ADD CONSTRAINT absence_decision_ck CHECK ((decision = ANY (ARRAY['NEEDS_REVIEW'::text, 'UNEXCUSED'::text, 'NOT_UNEXCUSED'::text])));
ALTER TABLE absence_decisions ADD CONSTRAINT absence_decisions_employee_id_work_date_key UNIQUE (employee_id, work_date);
ALTER TABLE absence_decisions ADD CONSTRAINT absence_decisions_pkey PRIMARY KEY (id);
