CREATE OR REPLACE FUNCTION tenant_template._contract_minutes(p_start time without time zone, p_end time without time zone)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$ select case when p_start = p_end then 0 when p_end > p_start then floor(extract(epoch from (p_end-p_start))/60)::integer else floor((extract(epoch from (time '24:00' - p_start)) + extract(epoch from p_end))/60)::integer end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_absence_decision_set(p_employee_id bigint, p_work_date date, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$ declare v_id bigint; v_actor text:=coalesce(auth.jwt()->>'email',''); begin if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if; if not exists(select 1 from tenant_template.employees where id=p_employee_id) then return jsonb_build_object('ok',false,'error','EMPLOYEE_NOT_FOUND'); end if; if p_decision not in ('NEEDS_REVIEW','UNEXCUSED','NOT_UNEXCUSED') then return jsonb_build_object('ok',false,'error','BAD_DECISION'); end if; insert into tenant_template.absence_decisions(employee_id,work_date,decision,note,decided_by_email,decided_at) values(p_employee_id,p_work_date,p_decision,nullif(p_note,''),v_actor,now()) on conflict(employee_id,work_date) do update set decision=excluded.decision,note=excluded.note,decided_by_email=excluded.decided_by_email,decided_at=now() returning id into v_id; return jsonb_build_object('ok',true,'id',v_id); end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_absence_decisions(p_from date, p_to date, p_employee_id bigint DEFAULT NULL::bigint)
 RETURNS SETOF absence_decisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$ begin if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if; return query select * from tenant_template.absence_decisions d where d.work_date between p_from and p_to and (p_employee_id is null or d.employee_id=p_employee_id) order by d.work_date,d.employee_id; end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_attendance_break_decision_save(p_store_id bigint, p_employee_id bigint, p_in_event_id bigint, p_break_provided boolean, p_compensate_30m boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template'
AS $function$
declare v_email text;
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 if not exists(select 1 from tenant_template.employees e where e.id=p_employee_id and e.store_id=p_store_id) then raise exception 'EMPLOYEE_STORE_MISMATCH'; end if;
 if not exists(select 1 from tenant_template.attendance_events a where a.id=p_in_event_id and a.employee_id=p_employee_id and a.event_type='IN') then raise exception 'IN_EVENT_NOT_FOUND'; end if;
 v_email:=coalesce(auth.jwt()->>'email','admin');
 insert into tenant_template.attendance_break_decisions(store_id,employee_id,in_event_id,break_provided,compensate_30m,updated_by,updated_at)
 values(p_store_id,p_employee_id,p_in_event_id,p_break_provided,case when p_break_provided=false then p_compensate_30m else false end,v_email,now())
 on conflict(in_event_id) do update set break_provided=excluded.break_provided,compensate_30m=excluded.compensate_30m,updated_by=excluded.updated_by,updated_at=now();
 return jsonb_build_object('ok',true);
end$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_attendance_break_decisions(p_store_id bigint, p_from timestamp without time zone, p_to timestamp without time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template'
AS $function$
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 return coalesce((select jsonb_agg(to_jsonb(x)) from (
   select b.* from tenant_template.attendance_break_decisions b
   join tenant_template.attendance_events e on e.id=b.in_event_id
   where b.store_id=p_store_id and e.event_at>=p_from and e.event_at<p_to order by e.event_at
 ) x),'[]'::jsonb);
end$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_clear_operations_demo()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 delete from tenant_template.recipe_versions where is_demo; delete from tenant_template.inventory_movements where is_demo; delete from tenant_template.inventory_items where is_demo; delete from tenant_template.operations_transactions where is_demo; return json_build_object('ok',true);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_close_payroll(p_ym text, p_rows json, p_fingerprint text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_actor text; r json; n int:=0; v_month date;
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 if p_ym !~ '^\\d{4}-\\d{2}$' then raise exception 'BAD_YM'; end if;
 v_month:=(p_ym||'-01')::date;
 if v_month>=date_trunc('month',now() at time zone 'Asia/Seoul')::date then raise exception 'CURRENT_OR_FUTURE_MONTH_CANNOT_CLOSE'; end if;
 if exists(select 1 from tenant_template.payroll_period where ym=p_ym and status='CLOSED') then raise exception 'PAYROLL_ALREADY_CLOSED'; end if;
 v_actor:=coalesce(auth.jwt()->>'email','admin');
 delete from tenant_template.payroll_snapshot where ym=p_ym;
 for r in select * from json_array_elements(p_rows) loop
   insert into tenant_template.payroll_snapshot(ym,employee_id,employee_name,hours,wage,weeks,base_pay,juhyu_pay,adjust,gross_pay,tax_rate,net_pay,memo,source_fingerprint,closed_by)
   values(p_ym,(r->>'employee_id')::bigint,r->>'employee_name',nullif(r->>'hours','')::numeric,nullif(r->>'wage','')::int,nullif(r->>'weeks','')::int,
   nullif(r->>'base_pay','')::int,nullif(r->>'juhyu_pay','')::int,coalesce(nullif(r->>'adjust','')::int,0),nullif(r->>'gross_pay','')::int,
   nullif(r->>'tax_rate','')::numeric,nullif(r->>'net_pay','')::int,r->>'memo',p_fingerprint,v_actor);
   n:=n+1;
 end loop;
 insert into tenant_template.payroll_period(ym,status,updated_by,updated_at) values(p_ym,'CLOSED',v_actor,now())
 on conflict(ym) do update set status='CLOSED',updated_by=v_actor,updated_at=now();
 return json_build_object('ok',true,'count',n);
end $function$
;
