CREATE OR REPLACE FUNCTION tenant_template.admin_contract_weekly_preview(p_contract_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$ declare c tenant_template.employment_contracts%rowtype; v_minutes numeric; v_pay numeric; begin if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if; select * into c from tenant_template.employment_contracts where id=p_contract_id; if not found then return jsonb_build_object('ok',false,'error','CONTRACT_NOT_FOUND'); end if; if c.payroll_type<>'HOURLY' then return jsonb_build_object('ok',true,'candidate',false,'reason','MONTHLY_POLICY_UNDEFINED'); end if; v_minutes:=c.weekly_contracted_minutes/5.0; v_pay:=(v_minutes/60.0)*c.hourly_wage; return jsonb_build_object('ok',true,'candidate',c.weekly_contracted_minutes>=900,'weekly_contracted_minutes',c.weekly_contracted_minutes,'base_weekly_holiday_minutes',v_minutes,'base_weekly_holiday_pay',round(v_pay),'policy_pending',jsonb_build_array('J1_MONTH_BOUNDARY','J2_PARTIAL_EMPLOYMENT_WEEK','UNEXCUSED_WEEK_ENTITLEMENT_APPLICATION')); end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_correct_event(p_action text, p_event_id bigint, p_employee_id bigint, p_new_at timestamp without time zone, p_new_type text, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_id bigint; v_actor text; v_new_utc timestamp; v_target bigint;
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 v_actor:=coalesce(auth.jwt()->>'email','admin');
 if p_action='VOID_ADD' then
   if p_event_id is null then raise exception 'CORRECTION_ID_REQUIRED'; end if;
   select id into v_target from event_corrections where id=p_event_id and employee_id=p_employee_id and action='ADD';
   if v_target is null then raise exception 'ADD_CORRECTION_NOT_FOUND'; end if;
   insert into event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
   values(null,p_employee_id,'VOID_ADD',null,null,p_reason,v_actor) returning id into v_id;
   update event_corrections set reason=coalesce(reason,'')||' [VOID_ADD:'||v_id||']' where id=v_target;
   return v_id;
 end if;
 if p_action='VOID' and p_event_id is null then raise exception 'EVENT_ID_REQUIRED'; end if;
 v_new_utc:=case when p_new_at is null then null else (p_new_at at time zone 'Asia/Seoul') at time zone 'UTC' end;
 insert into event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
 values(p_event_id,p_employee_id,p_action,v_new_utc,p_new_type,p_reason,v_actor) returning id into v_id;
 return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_create_employee(p_name text, p_pin text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions', 'pg_temp'
AS $function$
declare
  v_id bigint;
  v_store_id bigint;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  select id into v_store_id
  from tenant_template.stores
  where is_active=true
  order by case when id=1 then 0 else 1 end,id
  limit 1;
  if v_store_id is null then raise exception 'STORE_NOT_FOUND'; end if;
  insert into tenant_template.employees(name,pin_bcrypt,is_active,store_id)
  values(trim(p_name),crypt(p_pin,gen_salt('bf')),true,v_store_id)
  returning id into v_id;
  return v_id;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_create_employee_for_store(p_name text, p_pin text, p_store_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions', 'pg_temp'
AS $function$
declare
  v_id bigint;
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'NAME_REQUIRED'; end if;
  if p_pin !~ '^\d{4}$' then raise exception 'PIN_REQUIRED'; end if;
  if not exists(select 1 from tenant_template.stores where id=p_store_id and is_active=true) then raise exception 'STORE_NOT_FOUND'; end if;
  insert into tenant_template.employees(name,pin_bcrypt,is_active,store_id)
  values(trim(p_name),crypt(p_pin,gen_salt('bf')),true,p_store_id)
  returning id into v_id;
  return v_id;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_create_employee_onboarding(p_name text, p_pin text, p_started_on date, p_payroll_type text, p_hourly_wage integer, p_monthly_salary integer, p_tax_treatment text, p_business_deduction_rate numeric, p_night_allowance_enabled boolean, p_night_allowance_mode text, p_night_allowance_value numeric, p_night_allowance_start time without time zone, p_memo text, p_workdays jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions', 'pg_temp'
AS $function$
declare
  v_emp bigint;
  v_period jsonb;
  v_contract jsonb;
  v_period_id bigint;
  v_contract_id bigint;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'NAME_REQUIRED'; end if;
  if p_pin !~ '^\d{4}$' then raise exception 'PIN_REQUIRED'; end if;
  if p_started_on is null then raise exception 'START_DATE_REQUIRED'; end if;

  v_emp := tenant_template.admin_create_employee(trim(p_name),p_pin);

  v_period := tenant_template.admin_employment_period_set(
    null,v_emp,p_started_on,null,null
  );
  if coalesce((v_period->>'ok')::boolean,false) is not true then
    raise exception '%',coalesce(v_period->>'error','PERIOD_SAVE_FAILED');
  end if;
  v_period_id := (v_period->>'id')::bigint;

  v_contract := tenant_template.admin_employment_contract_set(
    null,v_period_id,p_started_on,null,p_payroll_type,p_hourly_wage,p_monthly_salary,
    p_tax_treatment,p_business_deduction_rate,coalesce(p_night_allowance_enabled,false),
    p_night_allowance_mode,p_night_allowance_value,coalesce(p_night_allowance_start,time '22:00'),
    p_memo,coalesce(p_workdays,'[]'::jsonb)
  );
  if coalesce((v_contract->>'ok')::boolean,false) is not true then
    raise exception '%',coalesce(v_contract->>'error','CONTRACT_SAVE_FAILED');
  end if;
  v_contract_id := (v_contract->>'id')::bigint;

  update tenant_template.employees
  set wage=case when p_payroll_type='HOURLY' then p_hourly_wage else null end,
      tax_rate=case when p_tax_treatment='BUSINESS_INCOME' then p_business_deduction_rate else tax_rate end,
      memo=nullif(p_memo,'')
  where id=v_emp;

  return jsonb_build_object('ok',true,'employee_id',v_emp,'period_id',v_period_id,'contract_id',v_contract_id);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_create_employee_onboarding_for_store(p_name text, p_pin text, p_started_on date, p_payroll_type text, p_hourly_wage integer, p_monthly_salary integer, p_tax_treatment text, p_business_deduction_rate numeric, p_night_allowance_enabled boolean, p_night_allowance_mode text, p_night_allowance_value numeric, p_night_allowance_start time without time zone, p_memo text, p_workdays jsonb, p_store_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions', 'pg_temp'
AS $function$
declare
  v_emp bigint;v_employee_no integer;v_period jsonb;v_contract jsonb;v_period_id bigint;v_contract_id bigint;
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'NAME_REQUIRED'; end if;
  if p_pin !~ '^\d{4}$' then raise exception 'PIN_REQUIRED'; end if;
  if p_started_on is null then raise exception 'START_DATE_REQUIRED'; end if;
  if not exists(select 1 from tenant_template.stores where id=p_store_id and is_active=true) then raise exception 'STORE_NOT_FOUND'; end if;
  v_emp:=tenant_template.admin_create_employee_for_store(trim(p_name),p_pin,p_store_id);
  select employee_no into v_employee_no from tenant_template.employees where id=v_emp;
  v_period:=tenant_template.admin_employment_period_set(null,v_emp,p_started_on,null,null);
  if coalesce((v_period->>'ok')::boolean,false) is not true then raise exception '%',coalesce(v_period->>'error','PERIOD_SAVE_FAILED'); end if;
  v_period_id:=(v_period->>'id')::bigint;
  v_contract:=tenant_template.admin_employment_contract_set(
    null,v_period_id,p_started_on,null,p_payroll_type,p_hourly_wage,p_monthly_salary,p_tax_treatment,
    p_business_deduction_rate,coalesce(p_night_allowance_enabled,false),p_night_allowance_mode,
    p_night_allowance_value,coalesce(p_night_allowance_start,time '22:00'),p_memo,coalesce(p_workdays,'[]'::jsonb)
  );
  if coalesce((v_contract->>'ok')::boolean,false) is not true then raise exception '%',coalesce(v_contract->>'error','CONTRACT_SAVE_FAILED'); end if;
  v_contract_id:=(v_contract->>'id')::bigint;
  update tenant_template.employees set
    wage=case when p_payroll_type='HOURLY' then p_hourly_wage else null end,
    tax_rate=case when p_tax_treatment='BUSINESS_INCOME' then p_business_deduction_rate else tax_rate end,
    memo=nullif(p_memo,'') where id=v_emp;
  return jsonb_build_object('ok',true,'employee_id',v_emp,'employee_no',v_employee_no,'period_id',v_period_id,'contract_id',v_contract_id,'store_id',p_store_id);
end
$function$
;
