CREATE OR REPLACE FUNCTION tenant_template.admin_employee_contract_statuses()
 RETURNS TABLE(employee_id bigint, contract_registered boolean, contract_effective boolean, document_attached boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  return query
  select e.id,
    exists(select 1 from employment_periods ep join employment_contracts c on c.employment_period_id=ep.id where ep.employee_id=e.id),
    exists(select 1 from employment_periods ep join employment_contracts c on c.employment_period_id=ep.id
      where ep.employee_id=e.id and c.effective_from<=current_date and (c.effective_to is null or c.effective_to>=current_date)),
    exists(select 1 from employee_documents d where d.employee_id=e.id)
  from employees e
  where e.is_active=true
  order by e.name;
end;
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_employment_bundle(p_employee_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$ declare v_result jsonb; begin if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if; if not exists(select 1 from tenant_template.employees where id=p_employee_id) then raise exception 'EMPLOYEE_NOT_FOUND'; end if; select jsonb_build_object('periods',coalesce((select jsonb_agg(to_jsonb(p) order by p.started_on desc,p.id desc) from tenant_template.employment_periods p where p.employee_id=p_employee_id),'[]'::jsonb),'contracts',coalesce((select jsonb_agg(to_jsonb(c) order by c.effective_from desc,c.id desc) from tenant_template.employment_contracts c join tenant_template.employment_periods p on p.id=c.employment_period_id where p.employee_id=p_employee_id),'[]'::jsonb),'workdays',coalesce((select jsonb_agg(to_jsonb(w) order by w.contract_id,w.weekday) from tenant_template.employment_contract_workdays w join tenant_template.employment_contracts c on c.id=w.contract_id join tenant_template.employment_periods p on p.id=c.employment_period_id where p.employee_id=p_employee_id),'[]'::jsonb)) into v_result; return v_result; end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_employment_contract_set(p_id bigint, p_employment_period_id bigint, p_effective_from date, p_effective_to date, p_payroll_type text, p_hourly_wage integer, p_monthly_salary integer, p_tax_treatment text, p_business_deduction_rate numeric, p_night_allowance_enabled boolean, p_night_allowance_mode text, p_night_allowance_value numeric, p_night_allowance_start time without time zone, p_memo text, p_workdays jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$ declare v_id bigint; v_actor text:=coalesce(auth.jwt()->>'email',''); v_period tenant_template.employment_periods%rowtype; v_w jsonb; v_weekday int; v_start time; v_end time; v_min int; v_total int:=0; begin if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if; select * into v_period from tenant_template.employment_periods where id=p_employment_period_id; if not found then return jsonb_build_object('ok',false,'error','PERIOD_NOT_FOUND'); end if; if p_effective_from is null or (p_effective_to is not null and p_effective_to<p_effective_from) then return jsonb_build_object('ok',false,'error','BAD_CONTRACT_DATES'); end if; if p_effective_from<v_period.started_on or (v_period.ended_on is not null and (p_effective_to is null or p_effective_to>v_period.ended_on)) then return jsonb_build_object('ok',false,'error','CONTRACT_OUTSIDE_EMPLOYMENT'); end if; if p_payroll_type not in ('HOURLY','MONTHLY') then return jsonb_build_object('ok',false,'error','BAD_PAYROLL_TYPE'); end if; if p_payroll_type='HOURLY' and (coalesce(p_hourly_wage,0)<=0 or p_monthly_salary is not null) then return jsonb_build_object('ok',false,'error','HOURLY_WAGE_REQUIRED'); end if; if p_payroll_type='MONTHLY' and (coalesce(p_monthly_salary,0)<=0 or p_hourly_wage is not null) then return jsonb_build_object('ok',false,'error','MONTHLY_SALARY_REQUIRED'); end if; if p_tax_treatment not in ('BUSINESS_INCOME','FOUR_INSURANCE') then return jsonb_build_object('ok',false,'error','BAD_TAX_TREATMENT'); end if; if p_tax_treatment='BUSINESS_INCOME' and (p_business_deduction_rate is null or p_business_deduction_rate<0 or p_business_deduction_rate>1) then return jsonb_build_object('ok',false,'error','BAD_BUSINESS_RATE'); end if; if p_tax_treatment='FOUR_INSURANCE' and p_business_deduction_rate is not null then return jsonb_build_object('ok',false,'error','FOUR_INSURANCE_RATE_MUST_BE_NULL'); end if; if coalesce(p_night_allowance_enabled,false) and (p_night_allowance_mode not in ('RATE','FLAT') or p_night_allowance_value is null or p_night_allowance_value<0) then return jsonb_build_object('ok',false,'error','BAD_NIGHT_ALLOWANCE'); end if; if jsonb_typeof(coalesce(p_workdays,'[]'::jsonb))<>'array' then return jsonb_build_object('ok',false,'error','BAD_WORKDAYS'); end if; if p_payroll_type='HOURLY' then if jsonb_array_length(coalesce(p_workdays,'[]'::jsonb))=0 then return jsonb_build_object('ok',false,'error','WORKDAYS_REQUIRED'); end if; for v_w in select value from jsonb_array_elements(coalesce(p_workdays,'[]'::jsonb)) loop begin v_weekday:=(v_w->>'weekday')::int; v_start:=(v_w->>'start')::time; v_end:=(v_w->>'end')::time; exception when others then return jsonb_build_object('ok',false,'error','BAD_WORKDAY_ROW'); end; if v_weekday<0 or v_weekday>6 or v_start=v_end then return jsonb_build_object('ok',false,'error','BAD_WORKDAY_ROW'); end if; v_min:=tenant_template._contract_minutes(v_start,v_end); if v_min<=0 then return jsonb_build_object('ok',false,'error','BAD_WORKDAY_ROW'); end if; v_total:=v_total+v_min; end loop; else if jsonb_array_length(coalesce(p_workdays,'[]'::jsonb))>0 then return jsonb_build_object('ok',false,'error','MONTHLY_WORKDAYS_NOT_SUPPORTED'); end if; end if; if exists(select 1 from tenant_template.employment_contracts x where x.employment_period_id=p_employment_period_id and (p_id is null or x.id<>p_id) and daterange(x.effective_from,coalesce(x.effective_to,'infinity'::date),'[]') && daterange(p_effective_from,coalesce(p_effective_to,'infinity'::date),'[]')) then return jsonb_build_object('ok',false,'error','CONTRACT_OVERLAP'); end if; if p_id is null then insert into tenant_template.employment_contracts(employment_period_id,effective_from,effective_to,payroll_type,hourly_wage,monthly_salary,weekly_contracted_minutes,tax_treatment,business_deduction_rate,night_allowance_enabled,night_allowance_mode,night_allowance_value,night_allowance_start,memo,created_by_email,updated_by_email) values(p_employment_period_id,p_effective_from,p_effective_to,p_payroll_type,p_hourly_wage,p_monthly_salary,v_total,p_tax_treatment,case when p_tax_treatment='BUSINESS_INCOME' then p_business_deduction_rate else null end,coalesce(p_night_allowance_enabled,false),case when p_night_allowance_enabled then p_night_allowance_mode else null end,case when p_night_allowance_enabled then p_night_allowance_value else null end,coalesce(p_night_allowance_start,time '22:00'),nullif(p_memo,''),v_actor,v_actor) returning id into v_id; else update tenant_template.employment_contracts set effective_from=p_effective_from,effective_to=p_effective_to,payroll_type=p_payroll_type,hourly_wage=p_hourly_wage,monthly_salary=p_monthly_salary,weekly_contracted_minutes=v_total,tax_treatment=p_tax_treatment,business_deduction_rate=case when p_tax_treatment='BUSINESS_INCOME' then p_business_deduction_rate else null end,night_allowance_enabled=coalesce(p_night_allowance_enabled,false),night_allowance_mode=case when p_night_allowance_enabled then p_night_allowance_mode else null end,night_allowance_value=case when p_night_allowance_enabled then p_night_allowance_value else null end,night_allowance_start=coalesce(p_night_allowance_start,time '22:00'),memo=nullif(p_memo,''),updated_by_email=v_actor,updated_at=now() where id=p_id and employment_period_id=p_employment_period_id returning id into v_id; if v_id is null then return jsonb_build_object('ok',false,'error','CONTRACT_NOT_FOUND'); end if; delete from tenant_template.employment_contract_workdays where contract_id=v_id; end if; if p_payroll_type='HOURLY' then for v_w in select value from jsonb_array_elements(coalesce(p_workdays,'[]'::jsonb)) loop v_weekday:=(v_w->>'weekday')::int; v_start:=(v_w->>'start')::time; v_end:=(v_w->>'end')::time; v_min:=tenant_template._contract_minutes(v_start,v_end); insert into tenant_template.employment_contract_workdays(contract_id,weekday,planned_start,planned_end,contracted_minutes) values(v_id,v_weekday,v_start,v_end,v_min); end loop; end if; return jsonb_build_object('ok',true,'id',v_id,'weekly_contracted_minutes',v_total); exception when unique_violation then return jsonb_build_object('ok',false,'error','DUPLICATE_WORKDAY'); end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_employment_period_contract_create(p_employee_id bigint, p_started_on date, p_ended_on date, p_period_note text, p_effective_from date, p_effective_to date, p_payroll_type text, p_hourly_wage integer, p_monthly_salary integer, p_tax_treatment text, p_business_deduction_rate numeric, p_night_allowance_enabled boolean, p_night_allowance_mode text, p_night_allowance_value numeric, p_night_allowance_start time without time zone, p_contract_memo text, p_workdays jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_period jsonb;
  v_contract jsonb;
  v_msg text;
begin
  if not tenant_template.is_admin() then
    raise exception 'NOT_AUTHORIZED';
  end if;

  begin
    v_period := tenant_template.admin_employment_period_set(
      null, p_employee_id, p_started_on, p_ended_on, p_period_note
    );
    if not coalesce((v_period->>'ok')::boolean,false) then
      raise exception 'ATOMIC_PERIOD:%', coalesce(v_period->>'error','SAVE_FAILED');
    end if;

    v_contract := tenant_template.admin_employment_contract_set(
      null,
      (v_period->>'id')::bigint,
      p_effective_from,
      p_effective_to,
      p_payroll_type,
      p_hourly_wage,
      p_monthly_salary,
      p_tax_treatment,
      p_business_deduction_rate,
      p_night_allowance_enabled,
      p_night_allowance_mode,
      p_night_allowance_value,
      p_night_allowance_start,
      p_contract_memo,
      p_workdays
    );
    if not coalesce((v_contract->>'ok')::boolean,false) then
      raise exception 'ATOMIC_CONTRACT:%', coalesce(v_contract->>'error','SAVE_FAILED');
    end if;

    return jsonb_build_object(
      'ok',true,
      'period_id',(v_period->>'id')::bigint,
      'contract_id',(v_contract->>'id')::bigint,
      'weekly_contracted_minutes',v_contract->'weekly_contracted_minutes'
    );
  exception when raise_exception then
    v_msg := sqlerrm;
    if v_msg like 'ATOMIC_PERIOD:%' then
      return jsonb_build_object('ok',false,'error',substring(v_msg from 15));
    elsif v_msg like 'ATOMIC_CONTRACT:%' then
      return jsonb_build_object('ok',false,'error',substring(v_msg from 17));
    end if;
    raise;
  end;
end;
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_employment_period_set(p_id bigint, p_employee_id bigint, p_started_on date, p_ended_on date DEFAULT NULL::date, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$ declare v_id bigint; v_actor text:=coalesce(auth.jwt()->>'email',''); begin if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if; if not exists(select 1 from tenant_template.employees where id=p_employee_id) then return jsonb_build_object('ok',false,'error','EMPLOYEE_NOT_FOUND'); end if; if p_started_on is null or (p_ended_on is not null and p_ended_on<p_started_on) then return jsonb_build_object('ok',false,'error','BAD_PERIOD_DATES'); end if; if exists(select 1 from tenant_template.employment_periods x where x.employee_id=p_employee_id and (p_id is null or x.id<>p_id) and daterange(x.started_on,coalesce(x.ended_on,'infinity'::date),'[]') && daterange(p_started_on,coalesce(p_ended_on,'infinity'::date),'[]')) then return jsonb_build_object('ok',false,'error','PERIOD_OVERLAP'); end if; if p_id is not null and exists(select 1 from tenant_template.employment_contracts c where c.employment_period_id=p_id and (c.effective_from<p_started_on or (p_ended_on is not null and (c.effective_to is null or c.effective_to>p_ended_on)))) then return jsonb_build_object('ok',false,'error','PERIOD_CONTRACT_CONFLICT'); end if; if p_id is null then insert into tenant_template.employment_periods(employee_id,started_on,ended_on,note,created_by_email,updated_by_email) values(p_employee_id,p_started_on,p_ended_on,nullif(p_note,''),v_actor,v_actor) returning id into v_id; else update tenant_template.employment_periods set started_on=p_started_on,ended_on=p_ended_on,note=nullif(p_note,''),updated_by_email=v_actor,updated_at=now() where id=p_id and employee_id=p_employee_id returning id into v_id; if v_id is null then return jsonb_build_object('ok',false,'error','PERIOD_NOT_FOUND'); end if; end if; return jsonb_build_object('ok',true,'id',v_id); end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_events(p_from timestamp without time zone, p_to timestamp without time zone)
 RETURNS SETOF attendance_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  return query
    select ev.id, ev.employee_id, ev.event_type,
      (ev.event_at at time zone 'UTC') at time zone 'Asia/Seoul' as event_at,
      (ev.server_received_at at time zone 'UTC') at time zone 'Asia/Seoul' as server_received_at,
      ev.device_id, ev.created_at, ev.client_reported_at, ev.substitute_for_employee_id
    from attendance_events ev
    where ev.event_at >= ((p_from at time zone 'Asia/Seoul') at time zone 'UTC')
      and ev.event_at < ((p_to at time zone 'Asia/Seoul') at time zone 'UTC')
    order by ev.employee_id, ev.event_at;
end;
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_events_with_corrections(p_from timestamp without time zone, p_to timestamp without time zone)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 return (select json_build_object(
 'events',coalesce((select json_agg(row_to_json(e)) from (
   select ev.id,ev.employee_id,ev.event_type,(ev.event_at at time zone 'UTC') at time zone 'Asia/Seoul' event_at
   from attendance_events ev join employees ee on ee.id=ev.employee_id
   where ev.event_at>=((p_from at time zone 'Asia/Seoul') at time zone 'UTC') and ev.event_at<((p_to at time zone 'Asia/Seoul') at time zone 'UTC')
   and (current_setting('request.jwt.claims',true)::jsonb ? 'sub' is false or ee.store_id is not null)
   order by ev.employee_id,ev.event_at) e),'[]'::json),
 'corrections',coalesce((select json_agg(row_to_json(c)) from (
   select ec.id,ec.event_id,ec.employee_id,ec.action,
          case when ec.new_event_at is null then null else (ec.new_event_at at time zone 'UTC') at time zone 'Asia/Seoul' end new_event_at,
          ec.new_event_type,ec.reason,ec.created_by,ec.created_at
   from event_corrections ec
   where ec.created_at >= (p_from at time zone 'Asia/Seoul')-interval '90 days'
   and not (ec.action='ADD' and ec.reason like '%[VOID_ADD:%')
   and ec.action<>'VOID_ADD') c),'[]'::json)));
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_grant(p_email text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_uid uuid; v_cnt int; v_norm text;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  perform pg_advisory_xact_lock(hashtext('admin_users_mutation'));
  v_norm := lower(trim(p_email));
  select count(*) into v_cnt from (select u.* from auth.users u join public.tenant_memberships tm on tm.user_id=u.id join public.tenants tt on tt.id=tm.tenant_id where tt.schema_name='tenant_template') where lower(trim(email))=v_norm;
  if v_cnt = 0 then return json_build_object('ok',false,'error','AUTH_USER_NOT_FOUND'); end if;
  if v_cnt > 1 then return json_build_object('ok',false,'error','AUTH_USER_AMBIGUOUS'); end if;
  select id into v_uid from (select u.* from auth.users u join public.tenant_memberships tm on tm.user_id=u.id join public.tenants tt on tt.id=tm.tenant_id where tt.schema_name='tenant_template') where lower(trim(email))=v_norm;
  -- 이미 관리자면 명시적으로 알림 (앱 결과 정확성)
  if exists (select 1 from tenant_template.admin_users where user_id=v_uid) then
    return json_build_object('ok',false,'error','ALREADY_ADMIN','user_id',v_uid);
  end if;
  insert into tenant_template.admin_users(user_id,email,note)
    values (v_uid, v_norm, 'granted by '||coalesce(auth.jwt()->>'email','admin'));
  return json_build_object('ok',true,'user_id',v_uid);
end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_hq_product_apply(p_product_id bigint, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  p tenant_template.hq_products%rowtype;
  v_comp jsonb;
  v_item_id bigint;
  v_recipe_id bigint;
  v_created boolean;
  v_store_count integer:=0;
  v_action text:=upper(trim(coalesce(p_action,'')));
  v_alias text;
  v_old_hq_items bigint[]:='{}';
begin
  if not tenant_template.is_hq_admin() and session_user not in ('postgres','supabase_admin') then raise exception 'NOT_AUTHORIZED'; end if;
  if v_action not in ('LAUNCH','DISCONTINUE') then raise exception 'INVALID_ACTION'; end if;
  select * into p from tenant_template.hq_products where id=p_product_id for update;
  if p.id is null then raise exception 'PRODUCT_NOT_FOUND'; end if;

  if v_action='LAUNCH' then
    select coalesce(array_agg(item_id),'{}') into v_old_hq_items
      from tenant_template.hq_product_items where product_id=p.id and created_by_hq;
    delete from tenant_template.hq_product_items where product_id=p.id;
    for v_comp in select * from jsonb_array_elements(p.component_blueprint) loop
      v_item_id:=nullif(v_comp->>'item_id','')::bigint;
      v_created:=coalesce(v_item_id=any(v_old_hq_items),false);
      if v_item_id is not null then
        update tenant_template.inventory_items set is_active=true,updated_at=now() where id=v_item_id returning id into v_item_id;
        if v_item_id is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
      else
        select i.id into v_item_id from tenant_template.inventory_items i where lower(i.sku)=lower(trim(v_comp->>'sku')) limit 1;
        if v_item_id is null then
          insert into tenant_template.inventory_items(sku,name,unit,is_active,reorder_level,pack_quantity,pack_unit,is_demo)
          values(trim(v_comp->>'sku'),trim(v_comp->>'name'),trim(v_comp->>'unit'),true,
            nullif(v_comp->>'reorder_level','')::numeric,nullif(v_comp->>'pack_quantity','')::numeric,
            nullif(trim(coalesce(v_comp->>'pack_unit','')),''),false)
          returning id into v_item_id;
          v_created:=true;
        else
          v_created:=coalesce(v_item_id=any(v_old_hq_items),false);
          update tenant_template.inventory_items set name=trim(v_comp->>'name'),unit=trim(v_comp->>'unit'),is_active=true,
            reorder_level=coalesce(nullif(v_comp->>'reorder_level','')::numeric,reorder_level),
            pack_quantity=coalesce(nullif(v_comp->>'pack_quantity','')::numeric,pack_quantity),
            pack_unit=coalesce(nullif(trim(coalesce(v_comp->>'pack_unit','')),''),pack_unit),updated_at=now()
          where id=v_item_id;
        end if;
      end if;
      insert into tenant_template.hq_product_items(product_id,item_id,quantity,created_by_hq)
      values(p.id,v_item_id,(v_comp->>'quantity')::numeric,v_created)
      on conflict(product_id,item_id) do update set quantity=excluded.quantity,
        created_by_hq=tenant_template.hq_product_items.created_by_hq or excluded.created_by_hq;
    end loop;

    if p.recipe_version_id is not null then
      update tenant_template.recipe_versions set effective_to=current_date where id=p.recipe_version_id and effective_to is null;
    end if;
    insert into tenant_template.recipe_versions(menu_key,menu_name,category,effective_from,effective_to,is_demo)
    values(p.product_key,p.name,p.category,current_date,null,false) returning id into v_recipe_id;
    insert into tenant_template.recipe_components(recipe_version_id,item_id,quantity)
      select v_recipe_id,item_id,quantity from tenant_template.hq_product_items where product_id=p.id;

    insert into tenant_template.store_product_assignments(product_id,store_id,status,applied_at,discontinued_at)
      select p.id,s.id,'ACTIVE',now(),null from tenant_template.stores s where s.is_active
      on conflict(product_id,store_id) do update set status='ACTIVE',applied_at=now(),discontinued_at=null;
    get diagnostics v_store_count=row_count;

    delete from tenant_template.hq_product_transaction_links where product_id=p.id;
    foreach v_alias in array p.sale_aliases loop
      insert into tenant_template.hq_product_transaction_links values(p.id,'SALE',v_alias) on conflict do nothing;
    end loop;
    foreach v_alias in array p.purchase_aliases loop
      insert into tenant_template.hq_product_transaction_links values(p.id,'PURCHASE',v_alias) on conflict do nothing;
    end loop;
    update tenant_template.hq_products set status='ACTIVE',effective_from=current_date,effective_to=null,
      scheduled_at=null,recipe_version_id=v_recipe_id,updated_at=now() where id=p.id;
  else
    if p.recipe_version_id is not null then
      update tenant_template.recipe_versions set effective_to=current_date where id=p.recipe_version_id and effective_to is null;
    end if;
    update tenant_template.store_product_assignments set status='DISCONTINUED',discontinued_at=now()
      where product_id=p.id and status='ACTIVE';
    get diagnostics v_store_count=row_count;
    update tenant_template.inventory_items i set is_active=false,updated_at=now()
      where exists(select 1 from tenant_template.hq_product_items pi where pi.product_id=p.id and pi.item_id=i.id and pi.created_by_hq)
        and not exists(select 1 from tenant_template.hq_product_items pi2 join tenant_template.hq_products p2 on p2.id=pi2.product_id
          where pi2.item_id=i.id and p2.id<>p.id and p2.status='ACTIVE');
    update tenant_template.hq_products set status='DISCONTINUED',effective_to=current_date,
      scheduled_at=null,updated_at=now() where id=p.id;
    v_recipe_id:=p.recipe_version_id;
  end if;

  insert into tenant_template.hq_product_rollouts(product_id,action,affected_store_count,recipe_version_id,details,actor_id)
  values(p.id,v_action,v_store_count,v_recipe_id,
    jsonb_build_object('product_key',p.product_key,'name',p.name,'component_count',jsonb_array_length(p.component_blueprint)),auth.uid());
  return jsonb_build_object('ok',true,'action',v_action,'product_id',p.id,'affected_store_count',v_store_count,'recipe_version_id',v_recipe_id);
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_hq_product_list()
 RETURNS TABLE(id bigint, product_key text, name text, category text, status text, effective_from date, effective_to date, scheduled_at timestamp with time zone, removal_scheduled_at timestamp with time zone, thumbnail_url text, sale_aliases text[], purchase_aliases text[], component_blueprint jsonb, recipe_version_id bigint, has_pending_changes boolean, active_store_count bigint, total_store_count bigint, sales_30d numeric, purchases_30d numeric, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  return query
  with assignment_counts as (
    select a.product_id,count(*) filter(where a.status='ACTIVE') as active_count
    from tenant_template.store_product_assignments a
    group by a.product_id
  ),
  transaction_totals as (
    select l.product_id,
      sum(t.total_amount) filter(where l.transaction_type='SALE') as sales_total,
      sum(t.total_amount) filter(where l.transaction_type='PURCHASE') as purchase_total
    from tenant_template.hq_product_transaction_links l
    join tenant_template.operations_transactions t
      on t.transaction_type=l.transaction_type
     and lower(t.counterparty)=lower(l.alias)
     and t.transacted_at>=now()-interval '30 days'
    group by l.product_id
  ),
  store_total as (
    select count(*)::bigint as value from tenant_template.stores where is_active
  )
  select p.id,p.product_key,p.name,p.category,p.status,p.effective_from,p.effective_to,
    p.scheduled_at,p.removal_scheduled_at,r.thumbnail_url,
    p.sale_aliases,p.purchase_aliases,p.component_blueprint,p.recipe_version_id,p.has_pending_changes,
    coalesce(a.active_count,0),s.value,
    coalesce(t.sales_total,0),coalesce(t.purchase_total,0),p.updated_at
  from tenant_template.hq_products p
  cross join store_total s
  left join tenant_template.recipe_versions r on r.id=p.recipe_version_id
  left join assignment_counts a on a.product_id=p.id
  left join transaction_totals t on t.product_id=p.id
  order by case p.status when 'ACTIVE' then 0 when 'SCHEDULED' then 1 when 'DRAFT' then 2 else 3 end,
    p.updated_at desc,p.name;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_hq_product_removal_schedule(p_product_ids bigint[], p_removal_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_at timestamptz;
  v_requested integer;
  v_updated integer;
begin
  if not tenant_template.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  v_requested:=coalesce(array_length(p_product_ids,1),0);
  if v_requested=0 then raise exception 'PRODUCT_REQUIRED'; end if;
  if p_removal_date is null or p_removal_date <= (now() at time zone 'Asia/Seoul')::date then
    raise exception 'FUTURE_DATE_REQUIRED';
  end if;
  if exists(
    select 1 from unnest(p_product_ids) requested(id)
    left join tenant_template.hq_products p on p.id=requested.id
    where p.id is null or p.status<>'ACTIVE'
  ) then
    raise exception 'PRODUCT_NOT_REMOVABLE';
  end if;
  v_at:=p_removal_date::timestamp at time zone 'Asia/Seoul';
  update tenant_template.hq_products
    set removal_scheduled_at=v_at,updated_at=now()
    where id=any(p_product_ids) and status='ACTIVE';
  get diagnostics v_updated=row_count;
  if v_updated<>v_requested then raise exception 'PRODUCT_SELECTION_MISMATCH'; end if;
  return jsonb_build_object('ok',true,'scheduled_count',v_updated,'removal_scheduled_at',v_at);
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_hq_product_save(p_product_id bigint, p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_id bigint;
  v_key text;
  v_name text;
  v_category text;
  v_components jsonb;
  v_comp jsonb;
begin
  if not tenant_template.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  v_name:=trim(coalesce(p_payload->>'name',''));
  v_key:=upper(regexp_replace(trim(coalesce(p_payload->>'product_key','')),'[^A-Za-z0-9_-]+','-','g'));
  v_category:=nullif(trim(coalesce(p_payload->>'category','')),'');
  v_components:=coalesce(p_payload->'components','[]'::jsonb);
  if v_name='' then raise exception 'PRODUCT_NAME_REQUIRED'; end if;
  if v_key='' then raise exception 'PRODUCT_KEY_REQUIRED'; end if;
  if jsonb_typeof(v_components)<>'array' or jsonb_array_length(v_components)=0 then raise exception 'COMPONENT_REQUIRED'; end if;
  for v_comp in select * from jsonb_array_elements(v_components) loop
    if coalesce((v_comp->>'quantity')::numeric,0)<=0 then raise exception 'INVALID_COMPONENT_QUANTITY'; end if;
    if nullif(v_comp->>'item_id','') is null and
       (trim(coalesce(v_comp->>'sku',''))='' or trim(coalesce(v_comp->>'name',''))='' or trim(coalesce(v_comp->>'unit',''))='')
    then raise exception 'NEW_ITEM_FIELDS_REQUIRED'; end if;
  end loop;
  if p_product_id is null then
    insert into tenant_template.hq_products(product_key,name,category,sale_aliases,purchase_aliases,component_blueprint,created_by)
    values(v_key,v_name,v_category,
      array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'sale_aliases','[]'::jsonb)) x where trim(x)<>''),
      array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'purchase_aliases','[]'::jsonb)) x where trim(x)<>''),
      v_components,auth.uid()) returning id into v_id;
  else
    update tenant_template.hq_products set product_key=v_key,name=v_name,category=v_category,
      sale_aliases=array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'sale_aliases','[]'::jsonb)) x where trim(x)<>''),
      purchase_aliases=array(select trim(x) from jsonb_array_elements_text(coalesce(p_payload->'purchase_aliases','[]'::jsonb)) x where trim(x)<>''),
      component_blueprint=v_components,updated_at=now()
    where id=p_product_id returning id into v_id;
    if v_id is null then raise exception 'PRODUCT_NOT_FOUND'; end if;
  end if;
  return v_id;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_hq_product_schedule(p_product_id bigint, p_launch_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_at timestamptz;
  v_status text;
  v_pending boolean;
begin
  if not tenant_template.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;

  select status,has_pending_changes into v_status,v_pending
  from tenant_template.hq_products where id=p_product_id for update;
  if v_status is null then raise exception 'PRODUCT_NOT_FOUND'; end if;

  if p_launch_date is null then
    if v_status='SCHEDULED' then
      update tenant_template.hq_products
        set status='DRAFT',scheduled_at=null,updated_at=now()
        where id=p_product_id;
      return jsonb_build_object('ok',true,'status','DRAFT','scheduled_at',null,'schedule_type','LAUNCH');
    elsif v_status='ACTIVE' and exists(select 1 from tenant_template.hq_products where id=p_product_id and scheduled_at is not null) then
      update tenant_template.hq_products set scheduled_at=null,updated_at=now() where id=p_product_id;
      return jsonb_build_object('ok',true,'status','ACTIVE','scheduled_at',null,'schedule_type','UPDATE');
    end if;
    raise exception 'PRODUCT_NOT_SCHEDULED';
  end if;

  if p_launch_date <= (now() at time zone 'Asia/Seoul')::date then
    raise exception 'FUTURE_DATE_REQUIRED';
  end if;
  v_at:=p_launch_date::timestamp at time zone 'Asia/Seoul';

  if v_status='ACTIVE' then
    if not coalesce(v_pending,false) then raise exception 'PRODUCT_HAS_NO_PENDING_CHANGES'; end if;
    update tenant_template.hq_products set scheduled_at=v_at,updated_at=now() where id=p_product_id;
    return jsonb_build_object('ok',true,'status','ACTIVE','scheduled_at',v_at,'schedule_type','UPDATE');
  end if;

  update tenant_template.hq_products
    set status='SCHEDULED',scheduled_at=v_at,effective_from=p_launch_date,updated_at=now()
    where id=p_product_id and status in ('DRAFT','SCHEDULED','DISCONTINUED')
    returning status into v_status;
  if v_status is null then raise exception 'PRODUCT_NOT_SCHEDULABLE'; end if;
  return jsonb_build_object('ok',true,'status',v_status,'scheduled_at',v_at,'schedule_type','LAUNCH');
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_items()
 RETURNS TABLE(id bigint, sku text, name text, unit text, is_active boolean, on_hand numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 return query select i.id,i.sku,i.name,i.unit,i.is_active,coalesce(sum(m.quantity),0)::numeric
 from tenant_template.inventory_items i left join tenant_template.inventory_movements m on m.item_id=i.id
 group by i.id,i.sku,i.name,i.unit,i.is_active order by i.is_active desc,i.name;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_manual_list(p_store_id bigint DEFAULT 1)
 RETURNS SETOF inventory_manual_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  return query
    select * from tenant_template.inventory_manual_items
    where store_id=p_store_id and is_active
    order by category nulls last,name;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_manual_save(p_id bigint, p_store_id bigint, p_name text, p_sku text, p_category text, p_unit text, p_on_hand numeric, p_target_level numeric, p_reorder_point numeric, p_thumbnail_url text)
 RETURNS inventory_manual_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare r tenant_template.inventory_manual_items;
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'name required'; end if;
  if coalesce(p_target_level,0)<0 or coalesce(p_reorder_point,0)<0 or coalesce(p_on_hand,0)<0 then raise exception 'stock values must be >= 0'; end if;
  if coalesce(p_target_level,0)>0 and coalesce(p_reorder_point,0)>coalesce(p_target_level,0) then raise exception 'reorder point must not exceed target level'; end if;
  if p_id is null then
    insert into tenant_template.inventory_manual_items(store_id,name,sku,category,unit,on_hand,target_level,reorder_point,thumbnail_url)
    values(coalesce(p_store_id,1),trim(p_name),nullif(trim(p_sku),''),nullif(trim(p_category),''),coalesce(nullif(trim(p_unit),''),'ea'),coalesce(p_on_hand,0),coalesce(p_target_level,0),coalesce(p_reorder_point,0),nullif(trim(p_thumbnail_url),''))
    on conflict(store_id,name) do update set sku=excluded.sku,category=excluded.category,unit=excluded.unit,on_hand=excluded.on_hand,target_level=excluded.target_level,reorder_point=excluded.reorder_point,thumbnail_url=excluded.thumbnail_url,updated_at=now()
    returning * into r;
  else
    update tenant_template.inventory_manual_items set name=trim(p_name),sku=nullif(trim(p_sku),''),category=nullif(trim(p_category),''),unit=coalesce(nullif(trim(p_unit),''),'ea'),on_hand=coalesce(p_on_hand,0),target_level=coalesce(p_target_level,0),reorder_point=coalesce(p_reorder_point,0),thumbnail_url=nullif(trim(p_thumbnail_url),''),updated_at=now()
    where id=p_id and store_id=coalesce(p_store_id,1) returning * into r;
  end if;
  return r;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_manual_save_v2(p_id bigint, p_store_id bigint, p_name text, p_sku text, p_category text, p_unit text, p_on_hand numeric, p_target_level numeric, p_reorder_point numeric, p_thumbnail_url text, p_source_item_id bigint DEFAULT NULL::bigint)
 RETURNS inventory_manual_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare r tenant_template.inventory_manual_items; v_source tenant_template.inventory_items%rowtype;
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if coalesce(p_on_hand,0)<0 or coalesce(p_target_level,0)<0 or coalesce(p_reorder_point,0)<0 then raise exception 'INVALID_STOCK'; end if;
  if coalesce(p_target_level,0)>0 and coalesce(p_reorder_point,0)>coalesce(p_target_level,0) then raise exception 'INVALID_REORDER_POINT'; end if;
  if p_source_item_id is not null then
    select * into v_source from tenant_template.inventory_items where id=p_source_item_id and is_active;
    if v_source.id is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
    p_name:=v_source.name; p_sku:=v_source.sku; p_unit:=v_source.unit;
  elsif nullif(trim(p_name),'') is null then
    raise exception 'NAME_REQUIRED';
  end if;
  if p_id is null then
    insert into tenant_template.inventory_manual_items(store_id,name,sku,category,unit,on_hand,target_level,reorder_point,thumbnail_url,source_item_id)
    values(p_store_id,trim(p_name),nullif(trim(p_sku),''),nullif(trim(p_category),''),coalesce(nullif(trim(p_unit),''),'ea'),coalesce(p_on_hand,0),coalesce(p_target_level,0),coalesce(p_reorder_point,0),nullif(trim(p_thumbnail_url),''),p_source_item_id)
    on conflict(store_id,name) do update set sku=excluded.sku,category=excluded.category,unit=excluded.unit,on_hand=excluded.on_hand,target_level=excluded.target_level,reorder_point=excluded.reorder_point,thumbnail_url=excluded.thumbnail_url,source_item_id=coalesce(excluded.source_item_id,tenant_template.inventory_manual_items.source_item_id),updated_at=now()
    returning * into r;
  else
    update tenant_template.inventory_manual_items set name=trim(p_name),sku=nullif(trim(p_sku),''),category=nullif(trim(p_category),''),unit=coalesce(nullif(trim(p_unit),''),'ea'),on_hand=coalesce(p_on_hand,0),target_level=coalesce(p_target_level,0),reorder_point=coalesce(p_reorder_point,0),thumbnail_url=nullif(trim(p_thumbnail_url),''),source_item_id=coalesce(p_source_item_id,source_item_id),updated_at=now()
    where id=p_id and store_id=p_store_id returning * into r;
  end if;
  if r.id is null then raise exception 'INVENTORY_SAVE_FAILED'; end if;
  return r;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_movements(p_item_id bigint DEFAULT NULL::bigint, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(id bigint, item_id bigint, item_name text, business_date date, movement_type text, quantity numeric, unit_cost bigint, source_type text, source_key text, note text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 return query select m.id,m.item_id,i.name,m.business_date,m.movement_type,m.quantity,m.unit_cost,m.source_type,m.source_key,m.note
 from tenant_template.inventory_movements m join tenant_template.inventory_items i on i.id=m.item_id
 where (p_item_id is null or m.item_id=p_item_id) and (p_from is null or m.business_date>=p_from) and (p_to is null or m.business_date<=p_to)
 order by m.business_date desc,m.id desc limit 1000;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_overview()
 RETURNS TABLE(id bigint, sku text, name text, unit text, is_active boolean, on_hand numeric, reorder_level numeric, inventory_value numeric, low_stock boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 return query
 select i.id,i.sku,i.name,i.unit,i.is_active,
   coalesce(sum(m.quantity),0)::numeric on_hand,i.reorder_level,
   coalesce(sum(m.quantity * coalesce(m.unit_cost,0)),0)::numeric inventory_value,
   (i.reorder_level is not null and coalesce(sum(m.quantity),0)<=i.reorder_level) low_stock
 from tenant_template.inventory_items i left join tenant_template.inventory_movements m on m.item_id=i.id
 group by i.id order by i.is_active desc,i.name;
end $function$
;
