CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_purchase_order_create(p_store_id bigint, p_item_id bigint, p_manual_item_id bigint, p_quantity numeric, p_note text DEFAULT NULL::text)
 RETURNS inventory_purchase_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare r tenant_template.inventory_purchase_orders; v_name text; v_unit text; v_stock text; v_order text; v_conv numeric;
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 if coalesce(p_quantity,0)<=0 then raise exception 'INVALID_QUANTITY'; end if;
 if (p_item_id is null)=(p_manual_item_id is null) then raise exception 'EXACTLY_ONE_ITEM_REQUIRED'; end if;
 if p_manual_item_id is not null then
   select name,unit,stock_unit,order_unit,conversion_quantity into v_name,v_unit,v_stock,v_order,v_conv
   from tenant_template.inventory_manual_items where id=p_manual_item_id and store_id=p_store_id and is_active;
 else
   select name,unit,stock_unit,order_unit,conversion_quantity into v_name,v_unit,v_stock,v_order,v_conv
   from tenant_template.inventory_items where id=p_item_id and is_active;
 end if;
 if v_name is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
 v_stock:=coalesce(nullif(v_stock,''),v_unit);
 v_order:=coalesce(nullif(v_order,''),v_unit);
 v_conv:=coalesce(v_conv,1);
 insert into tenant_template.inventory_purchase_orders(store_id,item_id,manual_item_id,item_name,unit,stock_unit,order_unit,conversion_quantity,ordered_quantity,note)
 values(p_store_id,p_item_id,p_manual_item_id,v_name,v_order,v_stock,v_order,v_conv,p_quantity,nullif(trim(p_note),''))
 returning * into r;
 return r;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_purchase_order_list(p_store_id bigint DEFAULT 1, p_open_only boolean DEFAULT true)
 RETURNS SETOF inventory_purchase_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 return query select * from tenant_template.inventory_purchase_orders
 where store_id=p_store_id and (not p_open_only or status in ('ORDERED','PARTIAL'))
 order by ordered_at desc,id desc;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_purchase_receive(p_order_id bigint, p_quantity numeric)
 RETURNS inventory_purchase_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare r tenant_template.inventory_purchase_orders; v_remaining numeric; v_stock_qty numeric; v_updated bigint;
begin
 select * into r from tenant_template.inventory_purchase_orders where id=p_order_id for update;
 if r.id is null then raise exception 'ORDER_NOT_FOUND'; end if;
 if not tenant_template.can_manage_store(r.store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 if r.status not in ('ORDERED','PARTIAL') then raise exception 'ORDER_NOT_RECEIVABLE'; end if;
 v_remaining:=r.ordered_quantity-r.received_quantity;
 if coalesce(p_quantity,0)<=0 or p_quantity>v_remaining then raise exception 'INVALID_RECEIVE_QUANTITY'; end if;
 v_stock_qty:=p_quantity*coalesce(r.conversion_quantity,1);
 if r.manual_item_id is not null then
   update tenant_template.inventory_manual_items set on_hand=on_hand+v_stock_qty,updated_at=now()
   where id=r.manual_item_id and store_id=r.store_id returning id into v_updated;
   if v_updated is null then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
 else
   if not exists(select 1 from tenant_template.inventory_items where id=r.item_id) then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
   insert into tenant_template.inventory_movements(item_id,business_date,movement_type,quantity,source_type,source_key,note)
   values(r.item_id,(now() at time zone 'Asia/Seoul')::date,'RECEIPT',v_stock_qty,'PURCHASE_ORDER',r.id::text,
          '발주 입고 '||p_quantity||' '||coalesce(r.order_unit,r.unit)||case when coalesce(r.conversion_quantity,1)<>1 then ' → '||v_stock_qty||' '||coalesce(r.stock_unit,r.unit) else '' end);
 end if;
 update tenant_template.inventory_purchase_orders
 set received_quantity=received_quantity+p_quantity,
     status=case when received_quantity+p_quantity>=ordered_quantity then 'RECEIVED' else 'PARTIAL' end,
     received_at=case when received_quantity+p_quantity>=ordered_quantity then now() else received_at end,
     updated_at=now()
 where id=r.id returning * into r;
 return r;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_inventory_unit_config_save(p_item_id bigint, p_stock_unit text, p_order_unit text, p_conversion_quantity numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare r tenant_template.inventory_items%rowtype;
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 if p_item_id is null then raise exception 'ITEM_REQUIRED'; end if;
 if nullif(btrim(p_stock_unit),'') is null or nullif(btrim(p_order_unit),'') is null then raise exception 'UNIT_REQUIRED'; end if;
 if p_conversion_quantity is null or p_conversion_quantity<=0 then raise exception 'INVALID_CONVERSION_QUANTITY'; end if;
 update tenant_template.inventory_items
 set stock_unit=btrim(p_stock_unit),order_unit=btrim(p_order_unit),conversion_quantity=p_conversion_quantity,
     pack_unit=btrim(p_order_unit),pack_quantity=p_conversion_quantity
 where id=p_item_id returning * into r;
 if not found then raise exception 'INVENTORY_ITEM_NOT_FOUND'; end if;
 return jsonb_build_object('ok',true,'id',r.id,'stock_unit',r.stock_unit,'order_unit',r.order_unit,'conversion_quantity',r.conversion_quantity);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_list_admins()
