 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  return query
    select a.user_id, u.email::text, a.note, a.created_at
    from tenant_template.admin_users a
    join (select u.* from auth.users u join public.tenant_memberships tm on tm.user_id=u.id join public.tenants tt on tt.id=tm.tenant_id where tt.schema_name='tenant_template') u on u.id = a.user_id
