CREATE OR REPLACE FUNCTION tenant_template.admin_operations_analytics(p_from date, p_to date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v json;
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 select json_build_object(
 'by_channel',coalesce((select json_agg(x) from(select coalesce(channel,'기타') channel,sum(total_amount) amount,count(*) transactions from tenant_template.operations_transactions where business_date between p_from and p_to and transaction_type='SALE' and status='CONFIRMED' group by 1 order by 2 desc)x),'[]'::json),
 'daily',coalesce((select json_agg(x) from(select business_date,sum(case when transaction_type='SALE' then total_amount when transaction_type='REFUND' then -total_amount else 0 end) sales,sum(case when transaction_type='PURCHASE' then total_amount else 0 end) purchases from tenant_template.operations_transactions where business_date between p_from and p_to and status='CONFIRMED' group by business_date order by business_date)x),'[]'::json),
 'open_reconciliation',(select count(*) from tenant_template.operations_reconciliation_issues where business_date between p_from and p_to and status='OPEN'),
 'low_stock',(select count(*) from (select i.id from tenant_template.inventory_items i left join tenant_template.inventory_movements m on m.item_id=i.id where i.is_active and i.reorder_level is not null group by i.id having coalesce(sum(m.quantity),0)<=i.reorder_level)s)
 ) into v; return v;
end $function$
;
