CREATE OR REPLACE FUNCTION tenant_template.admin_resolve_request(p_request_id bigint, p_approve boolean, p_reject_reason text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare r correction_requests%rowtype; v_actor text; v_action text;
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 v_actor:=coalesce(auth.jwt()->>'email','admin');
 select * into r from correction_requests where id=p_request_id and status='PENDING';
 if not found then return json_build_object('ok',false,'error','NOT_FOUND_OR_RESOLVED'); end if;
 if p_approve then
   if r.kind='MISSING_OUT' or r.kind='MISSING_IN' then v_action:='ADD'; else v_action:='EDIT_TIME'; end if;
   insert into event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
   values(r.event_id,r.employee_id,v_action,
          case when r.requested_at is null then null else (r.requested_at at time zone 'Asia/Seoul') at time zone 'UTC' end,
          coalesce(r.requested_type,case when r.kind='MISSING_OUT' then 'OUT' when r.kind='MISSING_IN' then 'IN' else null end),
          '직원 정정요청 승인: '||coalesce(r.note,''),v_actor);
   update correction_requests set status='APPROVED',resolved_by=v_actor,resolved_at=now() where id=p_request_id;
   return json_build_object('ok',true,'status','APPROVED');
 else
   update correction_requests set status='REJECTED',resolved_by=v_actor,resolved_at=now(),reject_reason=p_reject_reason where id=p_request_id;
   return json_build_object('ok',true,'status','REJECTED');
 end if;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_retire_employee(p_id bigint, p_ended_on date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_period_id bigint;
  v_start date;
  v_last_type text;
  v_retired_at timestamp := clock_timestamp() at time zone 'UTC';
  v_auto_checkout boolean := false;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  if p_ended_on is null then return jsonb_build_object('ok',false,'error','END_DATE_REQUIRED'); end if;
  if not exists(select 1 from tenant_template.employees where id=p_id) then
    return jsonb_build_object('ok',false,'error','EMPLOYEE_NOT_FOUND');
  end if;

  perform pg_advisory_xact_lock(hashtext('punch_emp_'||p_id::text));

  with latest_corr as (
    select distinct on(event_id) event_id,action,new_event_at,new_event_type
    from tenant_template.event_corrections
    where event_id is not null and employee_id=p_id
    order by event_id,created_at desc,id desc
  ), eff as (
    select e.id::numeric ord,
           case when c.action='EDIT_TYPE' and c.new_event_type is not null then c.new_event_type else e.event_type end typ,
           case when c.action='EDIT_TIME' and c.new_event_at is not null then c.new_event_at else e.event_at end at
    from tenant_template.attendance_events e
    left join latest_corr c on c.event_id=e.id
    where e.employee_id=p_id and coalesce(c.action,'')<>'VOID'
    union all
    select (1000000000000000::numeric+c.id),c.new_event_type,c.new_event_at
    from tenant_template.event_corrections c
    where c.employee_id=p_id and c.action='ADD'
      and c.new_event_at is not null and c.new_event_type is not null
  )
  select typ into v_last_type from eff where at is not null order by at desc,ord desc limit 1;

  if v_last_type='IN' then
    insert into tenant_template.attendance_events(employee_id,event_type,event_at,server_received_at,device_id)
    values(p_id,'OUT',v_retired_at,v_retired_at,'ADMIN_RETIRE');
    v_auto_checkout := true;
  end if;

  select id,started_on into v_period_id,v_start
  from tenant_template.employment_periods
  where employee_id=p_id and ended_on is null
  order by started_on desc,id desc limit 1;

  if v_period_id is not null then
    if p_ended_on < v_start then return jsonb_build_object('ok',false,'error','BAD_END_DATE'); end if;
    update tenant_template.employment_periods set ended_on=p_ended_on,updated_at=now()
    where id=v_period_id;
    update tenant_template.employment_contracts
      set effective_to=least(coalesce(effective_to,p_ended_on),p_ended_on),updated_at=now()
      where employment_period_id=v_period_id and effective_from<=p_ended_on
        and (effective_to is null or effective_to>p_ended_on);
  end if;

  update tenant_template.employees set is_active=false where id=p_id;
  return jsonb_build_object('ok',true,'employee_id',p_id,'ended_on',p_ended_on,'period_id',v_period_id,'auto_checkout',v_auto_checkout,'checkout_at',case when v_auto_checkout then v_retired_at else null end);
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_revoke(p_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_total int; v_deleted int;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  -- 1) 자기 자신 해제 금지
  if p_user_id = auth.uid() then
    return json_build_object('ok',false,'error','CANNOT_REVOKE_SELF');
  end if;
  -- 2) grant와 동일 키로 직렬화 (count/delete race 방지)
  perform pg_advisory_xact_lock(hashtext('admin_users_mutation'));
  -- 3) 대상이 실제 관리자인지 확인
  if not exists (select 1 from tenant_template.admin_users where user_id=p_user_id) then
    return json_build_object('ok',false,'error','ADMIN_NOT_FOUND');
  end if;
  -- 4) 마지막 관리자 lockout 방지
  select count(*) into v_total from tenant_template.admin_users;
  if v_total <= 1 then
    return json_build_object('ok',false,'error','CANNOT_REMOVE_LAST_ADMIN');
  end if;
  -- 5) 실제 삭제 + 삭제 행 수 검증
  delete from tenant_template.admin_users where user_id=p_user_id;
  get diagnostics v_deleted = row_count;
  if v_deleted <> 1 then
    -- 락 안에서 존재확인했으므로 정상적으론 도달 불가. 방어적 처리.
    raise exception 'REVOKE_UNEXPECTED_ROWCOUNT: %', v_deleted;
  end if;
  return json_build_object('ok',true,'removed',p_user_id);
end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_schedule_batch(p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_actor text;
  v_item jsonb;
  v_op text;
  v_status text;
  v_employee_id bigint;
  v_work_date date;
  v_start time;
  v_end time;
  v_memo text;
  v_rowcount integer;
  v_applied integer := 0;
  v_set_count integer := 0;
  v_delete_count integer := 0;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  if p_changes is null or jsonb_typeof(p_changes) <> 'array' then
    return jsonb_build_object('ok',false,'error','BAD_PAYLOAD');
  end if;
  if jsonb_array_length(p_changes) > 500 then
    return jsonb_build_object('ok',false,'error','TOO_MANY_CHANGES');
  end if;

  -- Pass 1: validate the complete batch before any write.
  for v_item in select value from jsonb_array_elements(p_changes)
  loop
    begin
      v_op := upper(coalesce(v_item->>'op','SET'));
      v_employee_id := nullif(v_item->>'employee_id','')::bigint;
      v_work_date := nullif(v_item->>'work_date','')::date;
    exception when others then
      return jsonb_build_object('ok',false,'error','BAD_ITEM','item',v_item);
    end;

    if v_employee_id is null or v_work_date is null then
      return jsonb_build_object('ok',false,'error','EMPLOYEE_DATE_REQUIRED','item',v_item);
    end if;
    if not exists (select 1 from tenant_template.employees where id=v_employee_id) then
      return jsonb_build_object('ok',false,'error','EMPLOYEE_NOT_FOUND','employee_id',v_employee_id);
    end if;

    if v_op = 'DELETE' then
      continue;
    elsif v_op <> 'SET' then
      return jsonb_build_object('ok',false,'error','BAD_OP','item',v_item);
    end if;

    v_status := upper(coalesce(v_item->>'status',''));
    if v_status not in ('WORK','OFF') then
      return jsonb_build_object('ok',false,'error','BAD_STATUS','item',v_item);
    end if;

    if v_status = 'WORK' then
      begin
        v_start := nullif(v_item->>'planned_start','')::time;
        v_end := nullif(v_item->>'planned_end','')::time;
      exception when others then
        return jsonb_build_object('ok',false,'error','BAD_TIME','item',v_item);
      end;
      if v_start is null or v_end is null then
        return jsonb_build_object('ok',false,'error','TIME_REQUIRED','item',v_item);
      end if;
      if v_start = v_end then
        return jsonb_build_object('ok',false,'error','ZERO_DURATION','item',v_item);
      end if;
    end if;
  end loop;

  -- Pass 2: apply only after the whole batch has passed validation.
  v_actor := coalesce(auth.jwt()->>'email','admin');
  for v_item in select value from jsonb_array_elements(p_changes)
  loop
    v_op := upper(coalesce(v_item->>'op','SET'));
    v_employee_id := (v_item->>'employee_id')::bigint;
    v_work_date := (v_item->>'work_date')::date;

    if v_op = 'DELETE' then
      delete from tenant_template.work_schedules
      where employee_id=v_employee_id and work_date=v_work_date;
      get diagnostics v_rowcount = row_count;
      v_delete_count := v_delete_count + v_rowcount;
      v_applied := v_applied + v_rowcount;
      continue;
    end if;

    v_status := upper(v_item->>'status');
    v_memo := nullif(trim(coalesce(v_item->>'memo','')),'');
    if v_status = 'WORK' then
      v_start := (v_item->>'planned_start')::time;
      v_end := (v_item->>'planned_end')::time;
    else
      v_start := null;
      v_end := null;
    end if;

    insert into tenant_template.work_schedules(
      employee_id,work_date,status,planned_start,planned_end,memo,updated_by_email,updated_at
    ) values (
      v_employee_id,v_work_date,v_status,v_start,v_end,v_memo,v_actor,now()
    )
    on conflict (employee_id,work_date) do update set
      status=excluded.status,
      planned_start=excluded.planned_start,
      planned_end=excluded.planned_end,
      memo=excluded.memo,
      updated_by_email=excluded.updated_by_email,
      updated_at=now()
    where (work_schedules.status,work_schedules.planned_start,work_schedules.planned_end,work_schedules.memo)
      is distinct from
      (excluded.status,excluded.planned_start,excluded.planned_end,excluded.memo);

    get diagnostics v_rowcount = row_count;
    v_set_count := v_set_count + v_rowcount;
    v_applied := v_applied + v_rowcount;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'requested',jsonb_array_length(p_changes),
    'applied',v_applied,
    'set_count',v_set_count,
    'delete_count',v_delete_count
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_schedule_delete(p_employee_id bigint, p_work_date date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_del int;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  delete from tenant_template.work_schedules where employee_id=p_employee_id and work_date=p_work_date;
  get diagnostics v_del = row_count;
  return json_build_object('ok',true,'deleted',v_del);
end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_schedule_list(p_from date, p_to date)
 RETURNS TABLE(id bigint, employee_id bigint, work_date date, status text, planned_start time without time zone, planned_end time without time zone, memo text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  return query
    select w.id,w.employee_id,w.work_date,w.status,w.planned_start,w.planned_end,w.memo
    from tenant_template.work_schedules w
    where w.work_date >= p_from and w.work_date <= p_to
    order by w.work_date, w.employee_id;
end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_schedule_set(p_employee_id bigint, p_work_date date, p_status text, p_start time without time zone, p_end time without time zone, p_memo text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_actor text; v_start time; v_end time;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  v_actor := coalesce(auth.jwt()->>'email','admin');
  if p_status not in ('WORK','OFF') then return json_build_object('ok',false,'error','BAD_STATUS'); end if;
  if not exists (select 1 from tenant_template.employees where id=p_employee_id) then
    return json_build_object('ok',false,'error','EMPLOYEE_NOT_FOUND'); end if;
  if p_status='WORK' then
    if p_start is null or p_end is null then return json_build_object('ok',false,'error','TIME_REQUIRED'); end if;
    if p_start = p_end then return json_build_object('ok',false,'error','ZERO_DURATION'); end if;
    v_start:=p_start; v_end:=p_end;
  else
    v_start:=null; v_end:=null;   -- OFF: 시각 없음 (CHECK도 강제)
  end if;
  insert into tenant_template.work_schedules(employee_id,work_date,status,planned_start,planned_end,memo,updated_by_email,updated_at)
    values (p_employee_id,p_work_date,p_status,v_start,v_end,nullif(trim(coalesce(p_memo,'')),''),v_actor,now())
  on conflict (employee_id,work_date) do update set
    status=excluded.status, planned_start=excluded.planned_start, planned_end=excluded.planned_end,
    memo=excluded.memo, updated_by_email=excluded.updated_by_email, updated_at=now();
  return json_build_object('ok',true);
end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_seed_operations_demo()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare beans bigint; milk bigint; cup bigint; lid bigint; syrup bigint; r bigint; d date:=current_date;
begin
 if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
 insert into tenant_template.inventory_items(sku,name,unit,reorder_level,is_demo) values
 ('DEMO-BEAN','[예시] 에스프레소 원두','g',3000,true),('[DEMO-MILK]','[예시] 우유','ml',6000,true),('DEMO-CUP','[예시] 16oz 컵','개',80,true),('DEMO-LID','[예시] 16oz 리드','개',80,true),('DEMO-SYRUP','[예시] 바닐라 시럽','ml',1000,true)
 on conflict(sku) do update set is_demo=true;
 select id into beans from tenant_template.inventory_items where sku='DEMO-BEAN'; select id into milk from tenant_template.inventory_items where sku='[DEMO-MILK]'; select id into cup from tenant_template.inventory_items where sku='DEMO-CUP'; select id into lid from tenant_template.inventory_items where sku='DEMO-LID'; select id into syrup from tenant_template.inventory_items where sku='DEMO-SYRUP';
 insert into tenant_template.inventory_movements(item_id,business_date,movement_type,quantity,unit_cost,source_type,source_key,note,is_demo) values
 (beans,d-20,'PURCHASE',5000,28,'DEMO','seed-beans','공개 커피 레시피 기반 UI 검증용 예시',true),(milk,d-10,'PURCHASE',12000,3,'DEMO','seed-milk','UI 검증용 예시',true),(cup,d-10,'PURCHASE',200,120,'DEMO','seed-cup','UI 검증용 예시',true),(lid,d-10,'PURCHASE',200,80,'DEMO','seed-lid','UI 검증용 예시',true),(syrup,d-10,'PURCHASE',2000,12,'DEMO','seed-syrup','UI 검증용 예시',true) on conflict(item_id,source_type,source_key) do nothing;
 insert into tenant_template.recipe_versions(menu_key,menu_name,effective_from,is_demo) values ('DEMO-AMERICANO','[예시] 아메리카노',d-365,true),('DEMO-LATTE','[예시] 카페라떼',d-365,true),('DEMO-VANILLA','[예시] 바닐라라떼',d-365,true) on conflict do nothing;
 select id into r from tenant_template.recipe_versions where menu_key='DEMO-AMERICANO' and is_demo order by id limit 1; insert into tenant_template.recipe_components(recipe_version_id,item_id,quantity) values(r,beans,18),(r,cup,1),(r,lid,1) on conflict do nothing;
 select id into r from tenant_template.recipe_versions where menu_key='DEMO-LATTE' and is_demo order by id limit 1; insert into tenant_template.recipe_components(recipe_version_id,item_id,quantity) values(r,beans,18),(r,milk,220),(r,cup,1),(r,lid,1) on conflict do nothing;
 select id into r from tenant_template.recipe_versions where menu_key='DEMO-VANILLA' and is_demo order by id limit 1; insert into tenant_template.recipe_components(recipe_version_id,item_id,quantity) values(r,beans,18),(r,milk,200),(r,syrup,20),(r,cup,1),(r,lid,1) on conflict do nothing;
 insert into tenant_template.operations_transactions(source,source_record_key,transaction_type,transacted_at,business_date,channel,counterparty,total_amount,status,metadata,is_demo)
 select 'DEMO','sale-'||g,'SALE',(d-(g%14))::timestamp + make_interval(hours=>8+(g%12)),d-(g%14),(array['매장','포장','배달'])[1+(g%3)],
 (array['아메리카노','카페라떼','바닐라라떼','카푸치노','카라멜마키아토','카페모카','콜드브루','에스프레소'])[1+(g%8)],
 (array[3500,4500,5000,4800,5500,5200,4900,3000])[1+(g%8)],'CONFIRMED',jsonb_build_object('demo',true,'qty',1),true
 from generate_series(1,160) g on conflict(source,source_store_key,source_record_key) do update set counterparty=excluded.counterparty,total_amount=excluded.total_amount,transacted_at=excluded.transacted_at,business_date=excluded.business_date,channel=excluded.channel,status='CONFIRMED',metadata=excluded.metadata,is_demo=true;
 return json_build_object('ok',true);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_set_period_employee(p_ym text, p_employee_id bigint, p_fields json)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  insert into payroll_period_employee(ym, employee_id,
      wage_override, juhyu_hours_override, juhyu_weeks_override, tax_rate_override, adjust_amount, memo, updated_by, updated_at)
    values (p_ym, p_employee_id,
      nullif(p_fields->>'wage_override','')::int,
      nullif(p_fields->>'juhyu_hours_override','')::numeric,
      nullif(p_fields->>'juhyu_weeks_override','')::int,
      nullif(p_fields->>'tax_rate_override','')::numeric,
      coalesce(nullif(p_fields->>'adjust_amount','')::int,0),
      nullif(p_fields->>'memo',''),
      coalesce(auth.jwt()->>'email','admin'), now())
  on conflict (ym, employee_id) do update set
      wage_override=excluded.wage_override,
      juhyu_hours_override=excluded.juhyu_hours_override,
      juhyu_weeks_override=excluded.juhyu_weeks_override,
      tax_rate_override=excluded.tax_rate_override,
      adjust_amount=excluded.adjust_amount,
      memo=excluded.memo, updated_by=excluded.updated_by, updated_at=now();
end; $function$
;
