CREATE OR REPLACE FUNCTION tenant_template.admin_snapshot(p_ym text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  return (select json_build_object(
    'status', coalesce((select status from payroll_period where ym=p_ym),'OPEN'),
    'fingerprint', (select source_fingerprint from payroll_snapshot where ym=p_ym limit 1),
    'rows', coalesce((select json_agg(row_to_json(s)) from (
      select employee_id,employee_name,hours,wage,weeks,base_pay,juhyu_pay,adjust,gross_pay,tax_rate,net_pay,memo,closed_by,closed_at
      from payroll_snapshot where ym=p_ym order by employee_name) s),'[]'::json)));
end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_payroll_contract_workdays(p_store_id bigint, p_month date)
 RETURNS TABLE(employee_id bigint, contract_id bigint, weekly_contracted_minutes integer, weekday smallint, contracted_minutes integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_start date:=date_trunc('month',p_month)::date; v_end date:=(date_trunc('month',p_month)+interval '1 month - 1 day')::date;
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 return query
 select e.id,c.id,c.weekly_contracted_minutes,w.weekday,w.contracted_minutes
 from tenant_template.employees e
 join tenant_template.employment_periods ep on ep.employee_id=e.id
 join tenant_template.employment_contracts c on c.employment_period_id=ep.id
 left join tenant_template.employment_contract_workdays w on w.contract_id=c.id
 where e.store_id=p_store_id and c.payroll_type='HOURLY'
   and c.effective_from<=v_end and (c.effective_to is null or c.effective_to>=v_start);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_payroll_contracts(p_store_id bigint, p_month date)
 RETURNS TABLE(employee_id bigint, contract_id bigint, payroll_type text, hourly_wage integer, monthly_salary integer, tax_treatment text, business_deduction_rate numeric, effective_from date, effective_to date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_start date:=date_trunc('month',p_month)::date; v_end date:=(date_trunc('month',p_month)+interval '1 month - 1 day')::date;
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 return query
 select distinct on (e.id)
   e.id,c.id,c.payroll_type,c.hourly_wage,c.monthly_salary,c.tax_treatment,c.business_deduction_rate,c.effective_from,c.effective_to
 from tenant_template.employees e
 join tenant_template.employment_periods ep on ep.employee_id=e.id
 join tenant_template.employment_contracts c on c.employment_period_id=ep.id
 where e.store_id=p_store_id
   and ep.started_on<=v_end and (ep.ended_on is null or ep.ended_on>=v_start)
   and c.effective_from<=v_end and (c.effective_to is null or c.effective_to>=v_start)
 order by e.id,c.effective_from desc,c.id desc;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_payroll_contracts_v2(p_store_id bigint, p_month date)
 RETURNS TABLE(employee_id bigint, contract_id bigint, payroll_type text, hourly_wage integer, monthly_salary integer, tax_treatment text, business_deduction_rate numeric, effective_from date, effective_to date, break_time_provided boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_start date:=date_trunc('month',p_month)::date;
  v_end date:=(date_trunc('month',p_month)+interval '1 month - 1 day')::date;
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  return query
  select distinct on (e.id)
    e.id,c.id,c.payroll_type,c.hourly_wage,c.monthly_salary,c.tax_treatment,
    c.business_deduction_rate,c.effective_from,c.effective_to,c.break_time_provided
  from tenant_template.employees e
  join tenant_template.employment_periods ep on ep.employee_id=e.id
  join tenant_template.employment_contracts c on c.employment_period_id=ep.id
  where e.store_id=p_store_id
    and ep.started_on<=v_end and (ep.ended_on is null or ep.ended_on>=v_start)
    and c.effective_from<=v_end and (c.effective_to is null or c.effective_to>=v_start)
  order by e.id,c.effective_from desc,c.id desc;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_product_retirement_finalize(p_store_id bigint, p_product_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_positive jsonb; v_untracked jsonb;
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if not exists(select 1 from tenant_template.store_product_assignments where store_id=p_store_id and product_id=p_product_id and status='RETIRING') then
    raise exception 'RETIREMENT_NOT_PENDING';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('name',i.name,'on_hand',m.on_hand,'unit',m.unit)),'[]'::jsonb)
  into v_positive
  from tenant_template.hq_product_items pi
  join tenant_template.inventory_items i on i.id=pi.item_id
  join tenant_template.inventory_manual_items m on m.store_id=p_store_id and m.source_item_id=i.id and m.is_active
  where pi.product_id=p_product_id and pi.created_by_hq and m.on_hand>0;

  select coalesce(jsonb_agg(jsonb_build_object('item_id',i.id,'name',i.name)),'[]'::jsonb)
  into v_untracked
  from tenant_template.hq_product_items pi
  join tenant_template.inventory_items i on i.id=pi.item_id
  where pi.product_id=p_product_id and pi.created_by_hq
    and not exists(select 1 from tenant_template.inventory_manual_items m where m.store_id=p_store_id and m.source_item_id=i.id and m.is_active);

  if jsonb_array_length(v_positive)>0 then
    return jsonb_build_object('ok',false,'error','STOCK_REMAINS','items',v_positive);
  end if;
  if jsonb_array_length(v_untracked)>0 then
    return jsonb_build_object('ok',false,'error','STOCK_NOT_TRACKED','items',v_untracked);
  end if;

  update tenant_template.store_product_assignments set status='DISCONTINUED',discontinued_at=now(),retirement_completed_at=now()
  where store_id=p_store_id and product_id=p_product_id and status='RETIRING';

  update tenant_template.inventory_items i set is_active=false,updated_at=now()
  where exists(select 1 from tenant_template.hq_product_items pi where pi.product_id=p_product_id and pi.item_id=i.id and pi.created_by_hq)
    and not exists(
      select 1 from tenant_template.hq_product_items pi2 join tenant_template.hq_products p2 on p2.id=pi2.product_id
      where pi2.item_id=i.id and p2.id<>p_product_id and p2.status='ACTIVE'
    )
    and not exists(
      select 1 from tenant_template.store_product_assignments a
      join tenant_template.hq_product_items pi3 on pi3.product_id=a.product_id and pi3.item_id=i.id
      where a.status in ('ACTIVE','RETIRING')
    );
  return jsonb_build_object('ok',true,'status','DISCONTINUED');
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_recipe_list(p_store_id bigint)
 RETURNS TABLE(product_id bigint, recipe_version_id bigint, menu_key text, menu_name text, category text, thumbnail_url text, instructions jsonb, components jsonb, is_overridden boolean, assignment_status text, retirement_requested_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 return query
 with src as (
   select v.menu_name,min(v.category) category,max(nullif(v.thumbnail_url,'')) thumbnail_url
   from tenant_template.recipe_source_variants v where v.category<>'토핑' group by v.menu_name
 ), base as (
  select hp.id product_id,hp.recipe_version_id,coalesce(hp.product_key,'source_'||md5(s.menu_name)) menu_key,
         s.menu_name,s.category,coalesce(s.thumbnail_url,rv.thumbnail_url,tenant_template.recipe_thumbnail_for_source(s.menu_name)) thumbnail_url,
         tenant_template.source_recipe_instructions(s.menu_name) instructions,tenant_template.source_recipe_components(s.menu_name) components
  from src s
  left join lateral (select p.* from tenant_template.hq_products p where p.status='ACTIVE' and regexp_replace(lower(p.name),'[^0-9a-z가-힣]','','g')=regexp_replace(lower(s.menu_name),'[^0-9a-z가-힣]','','g') order by p.id limit 1) hp on true
  left join tenant_template.recipe_versions rv on rv.id=hp.recipe_version_id
 )
 select b.product_id,b.recipe_version_id,b.menu_key,coalesce(nullif(o.menu_name,''),b.menu_name),coalesce(nullif(o.category,''),b.category),
        coalesce(nullif(o.thumbnail_url,''),b.thumbnail_url),coalesce(o.instructions,b.instructions),case when o.store_id is null then b.components else o.components end,
        o.store_id is not null,'ACTIVE'::text,null::timestamptz
 from base b left join tenant_template.store_recipe_overrides o on o.store_id=p_store_id and o.menu_key=b.menu_key
 order by coalesce(nullif(o.category,''),b.category),coalesce(nullif(o.menu_name,''),b.menu_name);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_recipe_override_clear(p_store_id bigint, p_menu_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  delete from tenant_template.store_recipe_overrides where store_id=p_store_id and menu_key=p_menu_key;
  return jsonb_build_object('ok',true);
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_recipe_override_save(p_store_id bigint, p_menu_key text, p_menu_name text, p_category text, p_components jsonb, p_thumbnail_url text, p_instructions jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_comp jsonb; v_item tenant_template.inventory_items%rowtype; v_normalized jsonb='[]'::jsonb;
begin
  if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
  if not exists(
    select 1 from tenant_template.hq_products p join tenant_template.store_product_assignments a on a.product_id=p.id
    where p.product_key=p_menu_key and a.store_id=p_store_id and a.status in ('ACTIVE','RETIRING')
  ) then raise exception 'RECIPE_NOT_FOUND'; end if;
  if jsonb_typeof(p_components)<>'array' or jsonb_array_length(p_components)=0 then
    raise exception 'COMPONENT_REQUIRED';
  end if;
  for v_comp in select * from jsonb_array_elements(p_components) loop
    select * into v_item from tenant_template.inventory_items
    where id=nullif(v_comp->>'item_id','')::bigint and is_active;
    if v_item.id is null or coalesce((v_comp->>'quantity')::numeric,0)<=0 then
      raise exception 'INVALID_COMPONENT';
    end if;
    v_normalized:=v_normalized||jsonb_build_array(jsonb_build_object(
      'item_id',v_item.id,'item_name',v_item.name,'unit',v_item.unit,
      'quantity',(v_comp->>'quantity')::numeric
    ));
  end loop;
  if p_instructions is not null and jsonb_typeof(p_instructions)<>'array' then
    raise exception 'INVALID_INSTRUCTIONS';
  end if;
  insert into tenant_template.store_recipe_overrides(
    store_id,menu_key,menu_name,category,thumbnail_url,instructions,components,updated_by,updated_at
  ) values(
    p_store_id,p_menu_key,nullif(trim(p_menu_name),''),nullif(trim(p_category),''),
    nullif(trim(p_thumbnail_url),''),p_instructions,v_normalized,auth.uid(),now()
  ) on conflict(store_id,menu_key) do update set
    menu_name=excluded.menu_name,category=excluded.category,
    thumbnail_url=excluded.thumbnail_url,instructions=excluded.instructions,components=excluded.components,
    updated_by=auth.uid(),updated_at=now();
  return jsonb_build_object('ok',true,'store_id',p_store_id,'menu_key',p_menu_key);
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_settings_get()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare s tenant_template.store_settings%rowtype;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  select * into s from tenant_template.store_settings where id=1;
  return json_build_object('open_minute',s.open_minute,'close_minute',s.close_minute,'close_grace_minutes',s.close_grace_minutes,'updated_at',s.updated_at);
end; $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_settings_get(p_store_id bigint DEFAULT NULL::bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare s tenant_template.store_settings%rowtype; v_store bigint:=coalesce(p_store_id,1);
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 select * into s from tenant_template.store_settings where store_id=v_store order by id limit 1;
 if not found then
   insert into tenant_template.store_settings(store_id,open_minute,close_minute,close_grace_minutes)
   values(v_store,420,1500,0) returning * into s;
 end if;
 return json_build_object('store_id',s.store_id,'open_minute',s.open_minute,'close_minute',s.close_minute,'updated_at',s.updated_at);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_settings_set(p_open_minute integer, p_close_minute integer, p_close_grace_minutes integer, p_store_id bigint DEFAULT NULL::bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare actor text; v_store bigint:=coalesce(p_store_id,1);
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 if p_open_minute is null or p_open_minute not between 0 and 1439 then return json_build_object('ok',false,'error','BAD_OPEN_TIME'); end if;
 if p_close_minute is null or p_close_minute not between 1 and 2879 or p_close_minute<=p_open_minute then return json_build_object('ok',false,'error','BAD_CLOSE_TIME'); end if;
 actor:=coalesce(auth.jwt()->>'email','admin');
 insert into tenant_template.store_settings(store_id,open_minute,close_minute,close_grace_minutes,updated_by,updated_at)
 values(v_store,p_open_minute,p_close_minute,0,actor,now())
 on conflict (store_id) where store_id is not null do update set open_minute=excluded.open_minute,close_minute=excluded.close_minute,close_grace_minutes=0,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
 return json_build_object('ok',true,'store_id',v_store);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.admin_store_settings_set(p_open_minute integer, p_close_minute integer, p_close_grace_minutes integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare actor text;
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  if p_open_minute is null or p_open_minute not between 0 and 1439 then return json_build_object('ok',false,'error','BAD_OPEN_TIME'); end if;
  if p_close_minute is null or p_close_minute not between 1 and 2879 or p_close_minute<=p_open_minute then return json_build_object('ok',false,'error','BAD_CLOSE_TIME'); end if;
  if p_close_grace_minutes is null or p_close_grace_minutes not between 0 and 360 then return json_build_object('ok',false,'error','BAD_GRACE'); end if;
  actor:=coalesce(auth.jwt()->>'email','admin');
  update tenant_template.store_settings set open_minute=p_open_minute,close_minute=p_close_minute,close_grace_minutes=p_close_grace_minutes,updated_by=actor,updated_at=now() where id=1;
  return json_build_object('ok',true);
end; $function$
;
