CREATE OR REPLACE FUNCTION tenant_template.admin_update_employee(p_id bigint, p_fields jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  update employees set
    wage        = coalesce((p_fields->>'wage')::int, wage),
    juhyu_hours = coalesce((p_fields->>'juhyu_hours')::numeric, juhyu_hours),
