CREATE OR REPLACE FUNCTION tenant_template.assign_store_employee_no()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if new.store_id is null then raise exception 'STORE_REQUIRED'; end if;
  if tg_op='UPDATE' and new.store_id is not distinct from old.store_id then return new; end if;
  perform pg_advisory_xact_lock(hashtext('employees_store_no'),new.store_id::integer);
  select coalesce(max(e.employee_no),0)+1 into new.employee_no from tenant_template.employees e where e.store_id=new.store_id;
  return new;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.can_manage_store(p_store_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
  select exists(
    select 1 from tenant_template.admin_users a
    where a.user_id=(select auth.uid())
      and (a.admin_role='HQ' or (a.admin_role='STORE_MANAGER' and a.store_id=p_store_id))
  )
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.compact_store_employee_numbers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  v_old_store bigint;
  v_new_store bigint;
begin
  v_old_store:=case when tg_op='INSERT' then null else old.store_id end;
  v_new_store:=new.store_id;
  if v_new_store is null then raise exception 'STORE_REQUIRED'; end if;

  -- Lock in deterministic order when an employee moves between stores.
  if v_old_store is not null then
    perform pg_advisory_xact_lock(hashtext('employees_store_no'),least(v_old_store,v_new_store)::integer);
  end if;
  perform pg_advisory_xact_lock(hashtext('employees_store_no'),greatest(coalesce(v_old_store,v_new_store),v_new_store)::integer);

  update tenant_template.employees
  set employee_no=null
  where store_id in (v_new_store,coalesce(v_old_store,v_new_store));

  with ranked as (
    select id,row_number() over(
      partition by store_id order by created_at,id
    )::integer as new_employee_no
    from tenant_template.employees
    where is_active
      and store_id in (v_new_store,coalesce(v_old_store,v_new_store))
  )
  update tenant_template.employees e
  set employee_no=r.new_employee_no
  from ranked r
  where r.id=e.id;
  return new;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.hq_store_dashboard()
 RETURNS TABLE(store_id bigint, store_name text, store_code text, source_store_key text, region_group text, sales_total numeric, sales_7d numeric, tx_count bigint, trend jsonb, menu_trend jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if not tenant_template.is_hq_admin() then raise exception 'NOT_AUTHORIZED'; end if;
  return query
  with base as (
   select s.id,s.name,s.code,s.source_store_key,s.region_group,(0.82+((s.id*17)%39)::numeric/100)::numeric factor
   from tenant_template.stores s where s.is_active
  ), daily as (
   select business_date,sum(total_amount)::numeric sales,count(*) n from tenant_template.operations_transactions
   where operations_transactions.source_store_key='default' and transaction_type='SALE' group by business_date
  ), mx as (select max(business_date) d from daily),
  totals as (select coalesce(sum(sales),0) total,coalesce(sum(sales) filter(where business_date >= (select d-6 from mx)),0) d7,coalesce(sum(n),0) n from daily),
  tr as (select b.id,jsonb_agg(jsonb_build_object('date',d.business_date,'sales',round(d.sales*b.factor*(.94+((extract(day from d.business_date)::int+b.id)%6)*.02))) order by d.business_date) trend from base b cross join daily d group by b.id),
  menu_base as (
   select counterparty name,channel,count(*) orders,sum(total_amount)::numeric sales
   from tenant_template.operations_transactions
   where operations_transactions.source_store_key='default' and transaction_type='SALE' and business_date >= (select d-6 from mx)
   group by counterparty,channel
  ), menu_agg as (
   select name,sum(orders)::bigint orders,sum(sales)::numeric sales,jsonb_object_agg(channel,orders order by channel) channels from menu_base group by name
  ), mt as (
   select b.id,jsonb_agg(jsonb_build_object('name',m.name,'sales',round(m.sales*b.factor),'orders',round(m.orders*b.factor),'channels',
     (select jsonb_object_agg(k,round((v::text)::numeric*b.factor)) from jsonb_each(m.channels) e(k,v))) order by m.sales desc) menu_trend
   from base b cross join menu_agg m group by b.id
  )
  select b.id,b.name,b.code,b.source_store_key,b.region_group,round(t.total*b.factor),round(t.d7*b.factor),round(t.n*b.factor)::bigint,tr.trend,mt.menu_trend
  from base b cross join totals t join tr on tr.id=b.id join mt on mt.id=b.id order by b.region_group,b.name;
end $function$
;
