CREATE OR REPLACE FUNCTION tenant_template.keep_inventory_for_retiring_products()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if old.is_active and not new.is_active and exists(
    select 1 from tenant_template.hq_product_items pi
    join tenant_template.store_product_assignments a on a.product_id=pi.product_id
    where pi.item_id=old.id and a.status='RETIRING'
