CREATE OR REPLACE FUNCTION tenant_template.my_events(p_employee_id bigint, p_pin text, p_from timestamp without time zone, p_to timestamp without time zone)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$
declare v_hash text;
begin
  select pin_bcrypt into v_hash from employees where id=p_employee_id and is_active=true;
  if v_hash is null then return json_build_object('ok',false,'error','NO_EMPLOYEE'); end if;
  if crypt(p_pin, v_hash) <> v_hash then return json_build_object('ok',false,'error','BAD_PIN'); end if;
  return json_build_object('ok',true,'events',
    coalesce((select json_agg(row_to_json(t)) from (
      select ev.id, ev.event_type,
        (ev.event_at at time zone 'UTC') at time zone 'Asia/Seoul' as event_at
      from attendance_events ev
      where ev.employee_id=p_employee_id
        and ev.event_at >= ((p_from at time zone 'Asia/Seoul') at time zone 'UTC')
        and ev.event_at < ((p_to at time zone 'Asia/Seoul') at time zone 'UTC')
      order by ev.event_at
    ) t),'[]'::json),
    'requests', coalesce((select json_agg(row_to_json(r)) from (
      select id, kind, requested_at, requested_type, note, status, created_at
      from correction_requests
      where employee_id=p_employee_id and created_at > now() - interval '60 days' order by created_at desc
    ) r),'[]'::json));
end;
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.normalize_hq_product_removal_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if new.status<>'ACTIVE' or (old.status='DISCONTINUED' and new.status='ACTIVE') then
    new.removal_scheduled_at:=null;
  end if;
  return new;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.notify_store_product_retirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare v_name text;
begin
  if old.status is distinct from 'RETIRING' and new.status='RETIRING' then
    select name into v_name from tenant_template.hq_products where id=new.product_id;
    insert into tenant_template.store_notifications(store_id,notification_type,product_id,title,message)
    values(new.store_id,'PRODUCT_RETIRING',new.product_id,
      coalesce(v_name,'상품')||' 판매 종료 안내',
      '전용 재료 재고를 소진한 뒤 레시피 화면에서 판매 종료를 확정하세요.');
  end if;
  return new;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.protect_store_product_retirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if old.status='ACTIVE' and new.status='DISCONTINUED' then
    new.status:='RETIRING';
    new.discontinued_at:=null;
    new.retirement_requested_at:=now();
    new.retirement_completed_at:=null;
  elsif new.status='ACTIVE' then
    new.retirement_requested_at:=null;
    new.retirement_completed_at:=null;
  end if;
  return new;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.punch(p_employee_id bigint, p_pin text, p_device text DEFAULT 'POS'::text, p_substitute_for_employee_id bigint DEFAULT NULL::bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$
declare
  v_hash text; v_store_id bigint; v_last_type text; v_type text;
  v_instant timestamptz:=clock_timestamp(); v_now_utc timestamp:=v_instant at time zone 'UTC'; v_now_kst timestamp:=v_instant at time zone 'Asia/Seoul';
  v_sub_name text; v_open_minute integer:=420; v_close_minute integer:=1500; v_reopen_minute integer; v_local_minute integer; v_close_clock_minute integer;
begin
  select pin_bcrypt,store_id into v_hash,v_store_id from tenant_template.employees where id=p_employee_id and is_active=true;
  if v_hash is null then return json_build_object('ok',false,'error','NO_EMPLOYEE'); end if;
  if crypt(p_pin,v_hash)<>v_hash then return json_build_object('ok',false,'error','BAD_PIN'); end if;
  perform pg_advisory_xact_lock(hashtext('punch_emp_'||p_employee_id::text));
  with latest_corr as (
    select distinct on(event_id) event_id,action,new_event_at,new_event_type from tenant_template.event_corrections
    where event_id is not null and employee_id=p_employee_id order by event_id,created_at desc,id desc
  ),eff as (
    select e.id::numeric ord,case when c.action='EDIT_TYPE' and c.new_event_type is not null then c.new_event_type else e.event_type end typ,
      case when c.action='EDIT_TIME' and c.new_event_at is not null then c.new_event_at else e.event_at end at
    from tenant_template.attendance_events e left join latest_corr c on c.event_id=e.id
    where e.employee_id=p_employee_id and coalesce(c.action,'')<>'VOID'
    union all
    select 1000000000000000::numeric+c.id,c.new_event_type,c.new_event_at from tenant_template.event_corrections c
    where c.employee_id=p_employee_id and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null
  ) select typ into v_last_type from eff where at is not null order by at desc,ord desc limit 1;
  v_type:=case when v_last_type='IN' then 'OUT' else 'IN' end;
  if v_type='IN' then
    select coalesce(open_minute,420),coalesce(close_minute,1500) into v_open_minute,v_close_minute
      from tenant_template.store_settings where id=coalesce(v_store_id,1);
    v_reopen_minute:=greatest(v_open_minute-60,0);
    v_local_minute:=extract(hour from v_now_kst)::integer*60+extract(minute from v_now_kst)::integer;
    if v_close_minute>=1440 then
      v_close_clock_minute:=v_close_minute-1440;
      if v_local_minute>=v_close_clock_minute and v_local_minute<v_reopen_minute then
        return json_build_object('ok',false,'error','STORE_CLOSED','open_minute',v_open_minute,'close_minute',v_close_minute,'reopen_minute',v_reopen_minute);
      end if;
    elsif v_local_minute>=v_close_minute or v_local_minute<v_reopen_minute then
      return json_build_object('ok',false,'error','STORE_CLOSED','open_minute',v_open_minute,'close_minute',v_close_minute,'reopen_minute',v_reopen_minute);
    end if;
  end if;
  if v_type='OUT' then p_substitute_for_employee_id:=null;
  elsif p_substitute_for_employee_id is not null then
    if p_substitute_for_employee_id=p_employee_id then return json_build_object('ok',false,'error','SUBSTITUTE_SELF'); end if;
    select name into v_sub_name from tenant_template.employees where id=p_substitute_for_employee_id and is_active=true;
    if v_sub_name is null then return json_build_object('ok',false,'error','SUBSTITUTE_NOT_ACTIVE'); end if;
  end if;
  insert into tenant_template.attendance_events(employee_id,event_type,event_at,server_received_at,device_id,substitute_for_employee_id)
  values(p_employee_id,v_type,v_now_utc,v_now_utc,coalesce(p_device,'POS'),p_substitute_for_employee_id);
  return json_build_object('ok',true,'type',v_type,'at',to_char(v_now_kst,'YYYY-MM-DD"T"HH24:MI:SS'),'name',(select name from tenant_template.employees where id=p_employee_id),
    'substitute_for_employee_id',p_substitute_for_employee_id,'substitute_for_name',v_sub_name);
end;$function$
;
CREATE OR REPLACE FUNCTION tenant_template.qa_rpc_contract_health()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
with x as (
 select
   (select count(*) from tenant_template.recipe_versions r where r.effective_to is null and not r.is_demo) active_recipes,
   (select count(*) from tenant_template.recipe_versions r where r.effective_to is null and not r.is_demo and not exists(select 1 from tenant_template.recipe_components c where c.recipe_version_id=r.id)) recipes_without_components,
   (select count(*) from tenant_template.inventory_items i where i.is_active and not i.is_demo) real_inventory_items,
   (select count(*) from tenant_template.hq_products p where p.status='ACTIVE' and p.recipe_version_id is null) products_without_recipe
)
select jsonb_build_object(
 'ok', recipes_without_components=0 and products_without_recipe=0,
 'active_recipes',active_recipes,
 'recipes_without_components',recipes_without_components,
 'real_inventory_items',real_inventory_items,
 'products_without_recipe',products_without_recipe
) from x
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.recipe_thumbnail_for_source(p_menu_name text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
  with q as (
    select regexp_replace(regexp_replace(lower(coalesce(p_menu_name,'')),'\s*\([^)]*\)\s*','','g'),'[^0-9a-z가-힣]','','g') k
  ), ranked as (
    select rv.thumbnail_url,
      case when regexp_replace(regexp_replace(lower(rv.menu_name),'\s*\([^)]*\)\s*','','g'),'[^0-9a-z가-힣]','','g')=(select k from q) then 0 else 9 end rank
    from tenant_template.recipe_versions rv
    where rv.effective_to is null and coalesce(rv.is_demo,false)=false and coalesce(rv.thumbnail_url,'')<>''
  )
  select thumbnail_url from ranked where rank=0 limit 1
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.request_correction(p_employee_id bigint, p_pin text, p_kind text, p_event_id bigint, p_requested_at timestamp without time zone, p_requested_type text, p_note text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$
declare v_hash text; v_id bigint;
begin
  select pin_bcrypt into v_hash from employees where id=p_employee_id and is_active=true;
  if v_hash is null then return json_build_object('ok',false,'error','NO_EMPLOYEE'); end if;
  if crypt(p_pin, v_hash) <> v_hash then return json_build_object('ok',false,'error','BAD_PIN'); end if;
  insert into correction_requests(employee_id,event_id,kind,requested_at,requested_type,note)
    values (p_employee_id,p_event_id,p_kind,p_requested_at,p_requested_type,p_note) returning id into v_id;
  return json_build_object('ok',true,'id',v_id);
