;
CREATE OR REPLACE FUNCTION tenant_template.source_recipe_components(p_name text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
with q as (
 select regexp_replace(lower(p_name),'[^0-9a-z가-힣]','','g') exact_key,
        regexp_replace(lower(regexp_replace(regexp_replace(p_name,'^[[:space:]]*1[lL][[:space:]]*','','i'),'[[:space:]]*1[lL][[:space:]]*$','','i')),'[^0-9a-z가-힣]','','g') base_key,
        p_name ~* '(^[[:space:]]*1[lL][[:space:]]*)|([[:space:]]*1[lL][[:space:]]*$)' is_1l
), picked as (
 select c.* from tenant_template.recipe_source_components c,q where regexp_replace(lower(c.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key
 union all
 select c.* from tenant_template.recipe_source_components c,q where q.is_1l and regexp_replace(lower(c.menu_name),'[^0-9a-z가-힣]','','g')=q.base_key and c.variant_label ~* '1[[:space:]]*[lL]'
 and not exists(select 1 from tenant_template.recipe_source_components x where regexp_replace(lower(x.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key)
)
select coalesce(jsonb_agg(jsonb_build_object('item_id',null,'item_name',ingredient_name,'unit',unit,'quantity',quantity,'quantity_text',case when quantity is null then unit else null end,'variant_label',variant_label,'source_line',source_line) order by variant_label,line_order),'[]'::jsonb) from picked
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.source_recipe_instructions(p_name text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
with q as (
 select regexp_replace(lower(p_name),'[^0-9a-z가-힣]','','g') exact_key,
        regexp_replace(lower(regexp_replace(regexp_replace(p_name,'^[[:space:]]*1[lL][[:space:]]*','','i'),'[[:space:]]*1[lL][[:space:]]*$','','i')),'[^0-9a-z가-힣]','','g') base_key,
        p_name ~* '(^[[:space:]]*1[lL][[:space:]]*)|([[:space:]]*1[lL][[:space:]]*$)' is_1l
), picked as (
 select v.* from tenant_template.recipe_source_variants v,q where regexp_replace(lower(v.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key
 union all
 select v.* from tenant_template.recipe_source_variants v,q where q.is_1l and regexp_replace(lower(v.menu_name),'[^0-9a-z가-힣]','','g')=q.base_key and v.variant_label ~* '1[[:space:]]*[lL]'
 and not exists(select 1 from tenant_template.recipe_source_variants x where regexp_replace(lower(x.menu_name),'[^0-9a-z가-힣]','','g')=q.exact_key)
)
select coalesce(jsonb_agg(jsonb_build_object('label',variant_label,'content',content) order by sort_order),'[]'::jsonb) from picked
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.staff_actual_attendance(p_employee_id bigint, p_pin text, p_from timestamp without time zone, p_to timestamp without time zone)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$
declare v_hash text; v_emp json;
begin
  select pin_bcrypt, json_build_object('id',id,'name',name,'employee_no',employee_no,'store_id',store_id)
    into v_hash,v_emp from employees where id=p_employee_id and is_active=true;
  if v_hash is null then return json_build_object('ok',false,'error','NO_EMPLOYEE'); end if;
  if crypt(p_pin,v_hash)<>v_hash then return json_build_object('ok',false,'error','BAD_PIN'); end if;
  return json_build_object(
    'ok',true,'employee',v_emp,
    'events',coalesce((select json_agg(row_to_json(t)) from (
      select ev.id,ev.employee_id,ev.event_type,
        (ev.event_at at time zone 'UTC') at time zone 'Asia/Seoul' as event_at
      from attendance_events ev
      where ev.employee_id=p_employee_id
        and ev.event_at>=((p_from at time zone 'Asia/Seoul') at time zone 'UTC')
        and ev.event_at<((p_to at time zone 'Asia/Seoul') at time zone 'UTC')
      order by ev.event_at
    ) t),'[]'::json),
    'corrections',coalesce((select json_agg(row_to_json(c)) from (
      select ec.id,ec.event_id,ec.employee_id,ec.action,
        case when ec.new_event_at is null then null else (ec.new_event_at at time zone 'UTC') at time zone 'Asia/Seoul' end as new_event_at,
        ec.new_event_type,ec.reason,ec.created_at
      from event_corrections ec
      where ec.employee_id=p_employee_id
        and (ec.new_event_at is null or (ec.new_event_at>=((p_from at time zone 'Asia/Seoul') at time zone 'UTC') and ec.new_event_at<((p_to at time zone 'Asia/Seoul') at time zone 'UTC')))
      order by ec.created_at
    ) c),'[]'::json)
  );
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.staff_recipe_list(p_employee_id bigint, p_pin text, p_store_id bigint)
 RETURNS TABLE(product_id bigint, recipe_version_id bigint, menu_key text, menu_name text, category text, thumbnail_url text, instructions jsonb, components jsonb, assignment_status text, retirement_requested_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions', 'pg_temp'
AS $function$
begin
 if not exists(select 1 from tenant_template.employees e where e.id=p_employee_id and e.store_id=p_store_id and e.is_active and e.pin_bcrypt=crypt(p_pin,e.pin_bcrypt)) then raise exception 'BAD_PIN'; end if;
 if not tenant_template.substitution_is_working(p_employee_id) then raise exception 'NOT_CLOCKED_IN'; end if;
 return query
 with src as (
   select v.menu_name,min(v.category) category,max(nullif(v.thumbnail_url,'')) thumbnail_url
   from tenant_template.recipe_source_variants v where v.category<>'토핑' group by v.menu_name
 ), base as (
  select hp.id product_id,hp.recipe_version_id,coalesce(hp.product_key,'source_'||md5(s.menu_name)) menu_key,s.menu_name,s.category,
         coalesce(s.thumbnail_url,rv.thumbnail_url,tenant_template.recipe_thumbnail_for_source(s.menu_name)) thumbnail_url,
         tenant_template.source_recipe_instructions(s.menu_name) instructions,tenant_template.source_recipe_components(s.menu_name) components
  from src s
  left join lateral (select p.* from tenant_template.hq_products p where p.status='ACTIVE' and regexp_replace(lower(p.name),'[^0-9a-z가-힣]','','g')=regexp_replace(lower(s.menu_name),'[^0-9a-z가-힣]','','g') order by p.id limit 1) hp on true
  left join tenant_template.recipe_versions rv on rv.id=hp.recipe_version_id
 )
 select b.product_id,b.recipe_version_id,b.menu_key,coalesce(nullif(o.menu_name,''),b.menu_name),coalesce(nullif(o.category,''),b.category),
        coalesce(nullif(o.thumbnail_url,''),b.thumbnail_url),coalesce(o.instructions,b.instructions),case when o.store_id is null then b.components else o.components end,
        'ACTIVE'::text,null::timestamptz
 from base b left join tenant_template.store_recipe_overrides o on o.store_id=p_store_id and o.menu_key=b.menu_key
 order by coalesce(nullif(o.category,''),b.category),coalesce(nullif(o.menu_name,''),b.menu_name);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.store_recipe_list_public(p_store_id bigint)
 RETURNS TABLE(product_id bigint, recipe_version_id bigint, menu_key text, menu_name text, category text, thumbnail_url text, instructions jsonb, components jsonb, assignment_status text, retirement_requested_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
with src as (
 select v.menu_name,min(v.category) category,max(nullif(v.thumbnail_url,'')) thumbnail_url
 from tenant_template.recipe_source_variants v where v.category<>'토핑' group by v.menu_name
), base as (
 select hp.id product_id,hp.recipe_version_id,coalesce(hp.product_key,'source_'||md5(s.menu_name)) menu_key,s.menu_name,s.category,
        coalesce(s.thumbnail_url,rv.thumbnail_url,tenant_template.recipe_thumbnail_for_source(s.menu_name)) thumbnail_url,
        tenant_template.source_recipe_instructions(s.menu_name) instructions,tenant_template.source_recipe_components(s.menu_name) components
 from src s
 left join lateral (select p.* from tenant_template.hq_products p where p.status='ACTIVE' and regexp_replace(lower(p.name),'[^0-9a-z가-힣]','','g')=regexp_replace(lower(s.menu_name),'[^0-9a-z가-힣]','','g') order by p.id limit 1) hp on true
 left join tenant_template.recipe_versions rv on rv.id=hp.recipe_version_id
)
select b.product_id,b.recipe_version_id,b.menu_key,coalesce(nullif(o.menu_name,''),b.menu_name),coalesce(nullif(o.category,''),b.category),
       coalesce(nullif(o.thumbnail_url,''),b.thumbnail_url),coalesce(o.instructions,b.instructions),case when o.store_id is null then b.components else o.components end,
       'ACTIVE'::text,null::timestamptz
from base b left join tenant_template.store_recipe_overrides o on o.store_id=p_store_id and o.menu_key=b.menu_key
where exists(select 1 from tenant_template.stores s where s.id=p_store_id and s.is_active)
order by coalesce(nullif(o.category,''),b.category),coalesce(nullif(o.menu_name,''),b.menu_name)
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_candidate_availability(p_requester bigint, p_pin text, p_start timestamp without time zone, p_end timestamp without time zone)
 RETURNS TABLE(employee_id bigint, available boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$ declare h text; begin select pin_bcrypt into h from employees where id=p_requester and is_active=true; if h is null or crypt(p_pin,h)<>h or p_end<=p_start then return; end if; return query select e.id, not substitution_is_working(e.id) and not substitution_schedule_conflict(e.id,p_start,p_end) and not exists(select 1 from substitution_requests r where r.substitute_employee_id=e.id and r.status in ('ACCEPTED','IN_PROGRESS') and r.work_start<p_end and r.work_end>p_start), case when substitution_is_working(e.id) then 'CURRENTLY_WORKING' when substitution_schedule_conflict(e.id,p_start,p_end) then 'WORK_SCHEDULE' when exists(select 1 from substitution_requests r where r.substitute_employee_id=e.id and r.status in ('ACCEPTED','IN_PROGRESS') and r.work_start<p_end and r.work_end>p_start) then 'SUBSTITUTION_RESERVED' else null end from employees e where e.is_active=true and e.id<>p_requester; end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_clock_in(p_request bigint, p_employee bigint, p_pin text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$
declare h text;r tenant_template.substitution_requests%rowtype;now_kst timestamp:=clock_timestamp() at time zone 'Asia/Seoul';now_utc timestamp:=clock_timestamp() at time zone 'UTC';last_type text;
begin
 select pin_bcrypt into h from employees where id=p_employee and is_active=true;
 if h is null or crypt(p_pin,h)<>h then return json_build_object('ok',false,'error','BAD_PIN'); end if;
 select * into r from substitution_requests where id=p_request and substitute_employee_id=p_employee for update;
 if not found or r.status<>'ACCEPTED' then return json_build_object('ok',false,'error','NOT_ACCEPTED'); end if;
 if now_kst < r.work_start-interval '60 minutes' then return json_build_object('ok',false,'error','TOO_EARLY'); end if;
 if now_kst >= r.work_end then return json_build_object('ok',false,'error','SHIFT_ENDED'); end if;
 perform pg_advisory_xact_lock(hashtext('punch_emp_'||p_employee::text));
 with latest as(
  select distinct on(event_id) event_id,action,new_event_type,new_event_at,created_by
  from event_corrections where event_id is not null and employee_id=p_employee order by event_id,created_at desc,id desc
 ),eff as(
  select e.id::numeric ord,
   case when l.action='EDIT_TYPE' and l.new_event_type is not null then l.new_event_type else e.event_type end typ,
   case when l.action='EDIT_TIME' and l.new_event_at is not null then
     case when coalesce(l.created_by,'')='system:auto-close' or coalesce(l.created_by,'') like 'substitution:%' then l.new_event_at+interval '9 hours' else l.new_event_at end
   else e.event_at+interval '9 hours' end at_kst
  from attendance_events e left join latest l on l.event_id=e.id
  where e.employee_id=p_employee and coalesce(l.action,'')<>'VOID'
  union all
  select 1000000000000000::numeric+c.id,c.new_event_type,
   case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end
  from event_corrections c where c.employee_id=p_employee and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null
 )
 select typ into last_type from eff where at_kst is not null order by at_kst desc,ord desc limit 1;
 if last_type='IN' then return json_build_object('ok',false,'error','ALREADY_WORKING'); end if;
 insert into attendance_events(employee_id,event_type,event_at,server_received_at,device_id) values(p_employee,'IN',now_utc,now_utc,'SUBSTITUTE:'||p_request);
 update substitution_requests set status='IN_PROGRESS' where id=p_request;
 return json_build_object('ok',true,'type','IN','at',to_char(now_kst,'YYYY-MM-DD"T"HH24:MI:SS'));
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_enforce_due()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template'
AS $function$
declare
  r record;
  n integer:=0;
  now_kst timestamp:=clock_timestamp() at time zone 'Asia/Seoul';
  planned integer;
  in_utc timestamp;
  out_utc timestamp;
  in_kst timestamp;
  out_kst timestamp;
  mins integer;
begin
  for r in
    select * from substitution_requests
    where status in('ACCEPTED','IN_PROGRESS') and work_end<=now_kst
    for update
  loop
    planned:=greatest(1,(extract(epoch from(r.work_end-r.work_start))/60)::integer);
    if r.status='ACCEPTED' then
      update substitution_requests set status='FAILED',actual_minutes=0,resolved_at=now() where id=r.id;
      n:=n+1;
      continue;
    end if;

    in_utc:=null; out_utc:=null; in_kst:=null; out_kst:=null; mins:=0;
    select event_at into in_utc
    from attendance_events
    where employee_id=r.substitute_employee_id and event_type='IN'
      and device_id='SUBSTITUTE:'||r.id::text
    order by id desc limit 1;

    if in_utc is null then
      update substitution_requests set status='FAILED',actual_minutes=0,resolved_at=now() where id=r.id;
      n:=n+1;
      continue;
    end if;
    in_kst:=in_utc+interval '9 hours';

    with latest_corr as (
      select distinct on(event_id) event_id,action,new_event_at,new_event_type
      from event_corrections
      where event_id is not null and employee_id=r.substitute_employee_id
      order by event_id,created_at desc,id desc
    ), eff as (
      select e.id::numeric ord,
             case when c.action='EDIT_TYPE' and c.new_event_type is not null then c.new_event_type else e.event_type end typ,
             case when c.action='EDIT_TIME' and c.new_event_at is not null then c.new_event_at else e.event_at end at
      from attendance_events e left join latest_corr c on c.event_id=e.id
      where e.employee_id=r.substitute_employee_id and coalesce(c.action,'')<>'VOID'
      union all
      select (1000000000000000::numeric+c.id),c.new_event_type,c.new_event_at
      from event_corrections c
      where c.employee_id=r.substitute_employee_id and c.action='ADD'
        and c.new_event_at is not null and c.new_event_type is not null
    )
    select at into out_utc from eff
    where typ='OUT' and at>in_utc
    order by at,ord limit 1;

    if out_utc is null then
      if not exists(
        select 1 from event_corrections
        where employee_id=r.substitute_employee_id and action='ADD'
          and reason='SYSTEM_SUBSTITUTE_END' and created_by='substitution:'||r.id::text
      ) then
        insert into event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
        values(null,r.substitute_employee_id,'ADD',r.work_end-interval '9 hours','OUT',
               'SYSTEM_SUBSTITUTE_END','substitution:'||r.id::text);
      end if;
      out_kst:=r.work_end;
    else
      out_kst:=out_utc+interval '9 hours';
    end if;

    mins:=greatest(0,(extract(epoch from(least(out_kst,r.work_end)-greatest(in_kst,r.work_start)))/60)::integer);
    update substitution_requests
    set status=case when mins>=planned then 'COMPLETED' else 'PARTIAL' end,
        actual_minutes=mins,resolved_at=now()
    where id=r.id;
    n:=n+1;
  end loop;
  return json_build_object('ok',true,'checked',n);
end;
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_is_working(p_employee bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'tenant_template'
AS $function$ with latest as (select distinct on(event_id) event_id,action,new_event_type,new_event_at,created_by from event_corrections where event_id is not null and employee_id=p_employee order by event_id,created_at desc,id desc), eff as (select e.id::numeric ord,case when l.action='EDIT_TYPE' and l.new_event_type is not null then l.new_event_type else e.event_type end typ,case when l.action='EDIT_TIME' and l.new_event_at is not null then l.new_event_at else e.event_at end at from attendance_events e left join latest l on l.event_id=e.id where e.employee_id=p_employee and coalesce(l.action,'')<>'VOID' union all select 1000000000000000::numeric+c.id,c.new_event_type,c.new_event_at from event_corrections c where c.employee_id=p_employee and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null) select coalesce((select typ='IN' from eff order by at desc,ord desc limit 1),false) $function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_refresh_one(p_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template'
AS $function$
declare r substitution_requests%rowtype;in_utc timestamp;out_kst timestamp;in_kst timestamp;mins integer:=0;now_kst timestamp:=clock_timestamp() at time zone 'Asia/Seoul';planned integer;
begin
 select * into r from substitution_requests where id=p_id for update;
 if not found or r.status not in('ACCEPTED','IN_PROGRESS','COMPLETED','PARTIAL','FAILED') then return; end if;
 select event_at into in_utc from attendance_events where employee_id=r.substitute_employee_id and event_type='IN' and device_id='SUBSTITUTE:'||r.id::text order by id desc limit 1;
 if in_utc is not null then
  in_kst:=in_utc+interval '9 hours';
  with latest as(
   select distinct on(event_id) event_id,action,new_event_type,new_event_at,created_by
   from event_corrections where event_id is not null and employee_id=r.substitute_employee_id order by event_id,created_at desc,id desc
  ),eff as(
   select e.id::numeric ord,
    case when l.action='EDIT_TYPE' and l.new_event_type is not null then l.new_event_type else e.event_type end typ,
    case when l.action='EDIT_TIME' and l.new_event_at is not null then
      case when coalesce(l.created_by,'')='system:auto-close' or coalesce(l.created_by,'') like 'substitution:%' then l.new_event_at+interval '9 hours' else l.new_event_at end
    else e.event_at+interval '9 hours' end at_kst
   from attendance_events e left join latest l on l.event_id=e.id
   where e.employee_id=r.substitute_employee_id and coalesce(l.action,'')<>'VOID'
   union all
   select 1000000000000000::numeric+c.id,c.new_event_type,
    case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end
   from event_corrections c where c.employee_id=r.substitute_employee_id and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null
  )
  select at_kst into out_kst from eff where typ='OUT' and at_kst>in_kst order by at_kst,ord limit 1;
 end if;
 planned:=greatest(1,(extract(epoch from(r.work_end-r.work_start))/60)::integer);
 if in_kst is not null and out_kst is not null then mins:=greatest(0,(extract(epoch from(least(out_kst,r.work_end)-greatest(in_kst,r.work_start)))/60)::integer); end if;
 if now_kst<r.work_end then
  update substitution_requests set actual_minutes=mins,status=case when in_kst is not null and out_kst is null then 'IN_PROGRESS' when in_kst is not null and out_kst is not null then 'PARTIAL' else 'ACCEPTED' end where id=r.id;
 else
  update substitution_requests set actual_minutes=case when status='COMPLETED' then greatest(actual_minutes,planned) else mins end,status=case when status='COMPLETED' then 'COMPLETED' when in_kst is null then 'FAILED' when mins>=planned then 'COMPLETED' else 'PARTIAL' end,resolved_at=coalesce(resolved_at,now()) where id=r.id;
 end if;
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_request_cancel(p_request bigint, p_employee bigint, p_pin text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$ declare h text; begin select pin_bcrypt into h from employees where id=p_employee and is_active=true; if h is null or crypt(p_pin,h)<>h then return json_build_object('ok',false,'error','BAD_PIN'); end if; update substitution_requests set status='CANCELLED',resolved_at=now() where id=p_request and requester_employee_id=p_employee and status in('REQUESTED','ACCEPTED'); if not found then return json_build_object('ok',false,'error','NOT_CANCELLABLE'); end if; return json_build_object('ok',true); end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_request_create(p_requester bigint, p_pin text, p_substitute bigint, p_start timestamp without time zone, p_end timestamp without time zone, p_note text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$ declare h text; rid bigint; begin select pin_bcrypt into h from employees where id=p_requester and is_active=true; if h is null or crypt(p_pin,h)<>h then return json_build_object('ok',false,'error','BAD_PIN'); end if; if p_requester=p_substitute or p_end<=p_start or not exists(select 1 from employees where id=p_substitute and is_active=true) then return json_build_object('ok',false,'error','INVALID_REQUEST'); end if; perform pg_advisory_xact_lock(hashtext('substitution_reservation_'||p_substitute::text)); if substitution_is_working(p_substitute) then return json_build_object('ok',false,'error','ALREADY_WORKING'); end if; if substitution_schedule_conflict(p_substitute,p_start,p_end) then return json_build_object('ok',false,'error','WORK_SCHEDULE_CONFLICT'); end if; if exists(select 1 from substitution_requests x where x.substitute_employee_id=p_substitute and x.status in ('ACCEPTED','IN_PROGRESS') and x.work_start<p_end and x.work_end>p_start) then return json_build_object('ok',false,'error','SUBSTITUTION_CONFLICT'); end if; insert into substitution_requests(requester_employee_id,substitute_employee_id,work_start,work_end,note) values(p_requester,p_substitute,p_start,p_end,left(nullif(trim(p_note),''),200)) returning id into rid; return json_build_object('ok',true,'id',rid); end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_request_list(p_employee bigint, p_pin text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$
declare h text;q record;
begin
  select pin_bcrypt into h from employees where id=p_employee and is_active=true;
  if h is null or crypt(p_pin,h)<>h then return json_build_object('ok',false,'error','BAD_PIN'); end if;

  perform substitution_enforce_due();
  for q in select id from substitution_requests
    where p_employee in(requester_employee_id,substitute_employee_id)
      and status in('ACCEPTED','IN_PROGRESS')
  loop
    perform substitution_refresh_one(q.id);
  end loop;

  return json_build_object('ok',true,'requests',(
    select coalesce(json_agg(x order by x.work_start desc),'[]'::json)
    from (
      select r.id,r.requester_employee_id,r.substitute_employee_id,a.name requester_name,b.name substitute_name,
             r.work_start,r.work_end,r.status,r.requested_at,r.accepted_at,r.resolved_at,r.note,r.actual_minutes
      from substitution_requests r
      join employees a on a.id=r.requester_employee_id
      join employees b on b.id=r.substitute_employee_id
      where p_employee in(r.requester_employee_id,r.substitute_employee_id)
    ) x
  ));
end;
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_request_respond(p_request bigint, p_employee bigint, p_pin text, p_accept boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'extensions'
AS $function$ declare h text; r substitution_requests%rowtype; begin select pin_bcrypt into h from employees where id=p_employee and is_active=true; if h is null or crypt(p_pin,h)<>h then return json_build_object('ok',false,'error','BAD_PIN'); end if; select * into r from substitution_requests where id=p_request and substitute_employee_id=p_employee and status='REQUESTED' for update; if not found then return json_build_object('ok',false,'error','NOT_PENDING'); end if; if p_accept then perform pg_advisory_xact_lock(hashtext('substitution_reservation_'||p_employee::text)); if substitution_is_working(p_employee) then return json_build_object('ok',false,'error','ALREADY_WORKING'); end if; if substitution_schedule_conflict(p_employee,r.work_start,r.work_end) then return json_build_object('ok',false,'error','WORK_SCHEDULE_CONFLICT'); end if; if exists(select 1 from substitution_requests x where x.id<>r.id and x.substitute_employee_id=p_employee and x.status in ('ACCEPTED','IN_PROGRESS') and x.work_start<r.work_end and x.work_end>r.work_start) then return json_build_object('ok',false,'error','SUBSTITUTION_CONFLICT'); end if; end if; update substitution_requests set status=case when p_accept then 'ACCEPTED' else 'REJECTED' end,accepted_at=case when p_accept then now() else null end,resolved_at=case when p_accept then null else now() end where id=r.id; return json_build_object('ok',true); end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.substitution_schedule_conflict(p_employee bigint, p_start timestamp without time zone, p_end timestamp without time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'tenant_template'
AS $function$ select exists(select 1 from work_schedules w where w.employee_id=p_employee and w.status='WORK' and w.planned_start is not null and w.planned_end is not null and (w.work_date::timestamp+w.planned_start)<p_end and (w.work_date::timestamp+w.planned_start + case when w.planned_end<=w.planned_start then interval '1 day' else interval '0 day' end + (w.planned_end-w.planned_start))>p_start) $function$
;
CREATE OR REPLACE FUNCTION tenant_template.system_apply_due_hq_products()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare
  r record;
  v_count integer:=0;
begin
  if session_user not in ('postgres','supabase_admin') then raise exception 'NOT_AUTHORIZED'; end if;
  for r in
    select id,'LAUNCH'::text as action,scheduled_at as due_at
    from tenant_template.hq_products
    where scheduled_at<=now()
      and (status='SCHEDULED' or (status='ACTIVE' and has_pending_changes))
    union all
    select id,'DISCONTINUE'::text as action,removal_scheduled_at as due_at
    from tenant_template.hq_products
    where status='ACTIVE' and removal_scheduled_at<=now()
    order by due_at
  loop
    perform tenant_template.admin_hq_product_apply(r.id,r.action);
    v_count:=v_count+1;
  end loop;
  return v_count;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.system_enforce_store_close(p_store_id bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare s tenant_template.store_settings%rowtype; now_kst timestamp without time zone:=now() at time zone 'Asia/Seoul'; active_from_kst timestamp without time zone; r record; v_business_date date; v_cutoff timestamp without time zone; v_closed integer:=0;
begin
 if not tenant_template.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if;
 select * into s from tenant_template.store_settings where store_id=p_store_id order by id desc limit 1;
 if not found then return json_build_object('ok',false,'error','STORE_SETTINGS_MISSING'); end if;
 active_from_kst:=s.auto_close_from at time zone 'Asia/Seoul';
 for r in
  with latest_corr as (
   select distinct on(c.event_id) c.event_id,c.action,c.new_event_at,c.new_event_type,c.created_by
   from tenant_template.event_corrections c join tenant_template.employees ce on ce.id=c.employee_id
   where c.event_id is not null and ce.store_id=p_store_id order by c.event_id,c.created_at desc,c.id desc
  ),eff as (
   select e.employee_id,case when c.action='EDIT_TYPE' and c.new_event_type is not null then c.new_event_type else e.event_type end event_type,
    case when c.action='EDIT_TIME' and c.new_event_at is not null then case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end else e.event_at+interval '9 hours' end event_at_kst,e.id::numeric ord
   from tenant_template.attendance_events e join tenant_template.employees ee on ee.id=e.employee_id left join latest_corr c on c.event_id=e.id
   where ee.store_id=p_store_id and coalesce(c.action,'')<>'VOID'
   union all
   select c.employee_id,c.new_event_type,case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end,1000000000000000::numeric+c.id
   from tenant_template.event_corrections c join tenant_template.employees ee on ee.id=c.employee_id
   where ee.store_id=p_store_id and c.action='ADD' and c.new_event_at is not null and c.new_event_type is not null
  ),last_eff as (
   select distinct on(employee_id) employee_id,event_type,event_at_kst from eff where event_at_kst is not null order by employee_id,event_at_kst desc,ord desc
  ) select * from last_eff where event_type='IN'
 loop
  v_business_date:=r.event_at_kst::date-case when (extract(hour from r.event_at_kst)::int*60+extract(minute from r.event_at_kst)::int)<s.open_minute then 1 else 0 end;
  v_cutoff:=v_business_date::timestamp+interval '26 hours';
  if v_cutoff>=active_from_kst and now_kst>=v_cutoff and v_cutoff>=r.event_at_kst then
   if not exists(select 1 from tenant_template.event_corrections where employee_id=r.employee_id and action='ADD' and reason='SYSTEM_STORE_CLOSE' and created_by='system:auto-close' and new_event_at=v_cutoff-interval '9 hours') then
    insert into tenant_template.event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by) values(null,r.employee_id,'ADD',v_cutoff-interval '9 hours','OUT','SYSTEM_STORE_CLOSE','system:auto-close');v_closed:=v_closed+1;
   end if;
  end if;
 end loop;
 return json_build_object('ok',true,'closed',v_closed,'store_id',p_store_id,'checked_at',now_kst,'active_from',active_from_kst,'hard_stop_minute',1560);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.system_enforce_store_close()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
declare now_kst timestamp without time zone:=now() at time zone 'Asia/Seoul'; r record; v_business_date date; v_cutoff timestamp without time zone; v_closed integer:=0;
begin
 for r in
  with latest_corr as (
   select distinct on(event_id) event_id,action,new_event_at,new_event_type,created_by
   from tenant_template.event_corrections where event_id is not null order by event_id,created_at desc,id desc
  ),eff as (
   select e.employee_id,
    case when c.action='EDIT_TYPE' and c.new_event_type is not null then c.new_event_type else e.event_type end event_type,
    case when c.action='EDIT_TIME' and c.new_event_at is not null then
      case when coalesce(c.created_by,'')='system:auto-close' or coalesce(c.created_by,'') like 'substitution:%' then c.new_event_at+interval '9 hours' else c.new_event_at end
      else e.event_at+interval '9 hours' end event_at_kst,e.id::numeric ord
   from tenant_template.attendance_events e left join latest_corr c on c.event_id=e.id where coalesce(c.action,'')<>'VOID'
   union all
   select employee_id,new_event_type,case when coalesce(created_by,'')='system:auto-close' or coalesce(created_by,'') like 'substitution:%' then new_event_at+interval '9 hours' else new_event_at end,1000000000000000::numeric+id
   from tenant_template.event_corrections where action='ADD' and new_event_at is not null and new_event_type is not null
  ),last_eff as (
   select distinct on(employee_id) employee_id,event_type,event_at_kst from eff where event_at_kst is not null order by employee_id,event_at_kst desc,ord desc
  )
  select le.*,coalesce(ss.open_minute,420) open_minute,ss.auto_close_from
  from last_eff le join tenant_template.employees e on e.id=le.employee_id
  left join lateral (select * from tenant_template.store_settings x where x.store_id=e.store_id order by x.id desc limit 1) ss on true
  where le.event_type='IN'
 loop
  v_business_date:=r.event_at_kst::date-case when (extract(hour from r.event_at_kst)::int*60+extract(minute from r.event_at_kst)::int)<r.open_minute then 1 else 0 end;
  v_cutoff:=v_business_date::timestamp+interval '26 hours';
  if now_kst>=v_cutoff and v_cutoff>=r.event_at_kst and (r.auto_close_from is null or v_cutoff>=r.auto_close_from at time zone 'Asia/Seoul') then
   if not exists(select 1 from tenant_template.event_corrections where employee_id=r.employee_id and action='ADD' and reason='SYSTEM_STORE_CLOSE' and created_by='system:auto-close' and new_event_at=v_cutoff-interval '9 hours') then
    insert into tenant_template.event_corrections(event_id,employee_id,action,new_event_at,new_event_type,reason,created_by)
    values(null,r.employee_id,'ADD',v_cutoff-interval '9 hours','OUT','SYSTEM_STORE_CLOSE','system:auto-close');v_closed:=v_closed+1;
   end if;
  end if;
 end loop;
 return json_build_object('ok',true,'closed',v_closed,'checked_at',now_kst,'hard_stop_minute',1560);
end $function$
;
CREATE OR REPLACE FUNCTION tenant_template.track_hq_product_pending_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  if new.recipe_version_id is distinct from old.recipe_version_id and new.status='ACTIVE' then
    new.has_pending_changes:=false;
  elsif old.status='ACTIVE' and (
    new.product_key is distinct from old.product_key or
    new.name is distinct from old.name or
    new.category is distinct from old.category or
    new.sale_aliases is distinct from old.sale_aliases or
    new.purchase_aliases is distinct from old.purchase_aliases or
    not (
      coalesce(new.component_blueprint,'[]'::jsonb) @> coalesce(old.component_blueprint,'[]'::jsonb) and
      coalesce(old.component_blueprint,'[]'::jsonb) @> coalesce(new.component_blueprint,'[]'::jsonb)
    )
  ) then
    new.has_pending_changes:=true;
  end if;
  return new;
end
$function$
;
CREATE OR REPLACE FUNCTION tenant_template.ws_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'tenant_template', 'pg_temp'
AS $function$
begin
  insert into tenant_template.work_schedule_history(schedule_id,employee_id,work_date,status,planned_start,planned_end,memo,updated_by_email,op)
    values (OLD.id,OLD.employee_id,OLD.work_date,OLD.status,OLD.planned_start,OLD.planned_end,OLD.memo,OLD.updated_by_email,TG_OP);
  return OLD;   -- (BEFORE 트리거: UPDATE는 NEW 반환이 관례지만, 여기선 값만 백업. AFTER로 두어 안전하게)
end; $function$
;
